try {
  if (isLogin) {
    const res = await login(email, pass);
    if (!res.success) setErrorMsg(res.message || 'Login failed');
  } else {
    const res = await signup(email, pass, businessName);
    if (!res.success) {
      setErrorMsg(res.message || 'Signup failed');
    } else if (res.message) {
      setInfoMsg(res.message);
    }
  }
} catch (err) {
  setErrorMsg('An unexpected error occurred. Please try again.');
} finally {
  setLoading(false);
}
{errorMsg && (
      <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-800 rounded-2xl flex items-start gap-3 text-red-600 dark:text-red-400 text-sm animate-in fade-in slide-in-from-top-2">
        <AlertCircle className="w-5 h-5 flex-shrink-0" />
        <p className="font-medium leading-tight">{errorMsg}</p>
      </div>
    )}

    {infoMsg && (
      <div className="mb-6 p-4 bg-emerald-50 dark:bg-emerald-900/10 border border-emerald-200 dark:border-emerald-800 rounded-2xl flex items-start gap-3 text-emerald-600 dark:text-emerald-400 text-sm animate-in fade-in slide-in-from-top-2">
        <ShieldCheck className="w-5 h-5 flex-shrink-0" />
        <p className="font-medium leading-tight">{infoMsg}</p>
      </div>
    )}

    <form onSubmit={handleSubmit} className="space-y-5">
      {!isLogin && (
        <div className="space-y-2 animate-in slide-in-from-top-2">
          <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Business Name</label>
