            type="text" 
            required
            className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-none outline-none focus:ring-2 ring-primary-500 transition-all font-bold"
            placeholder="e.g. AbuHanif Computer"
            value={businessName}
            onChange={e => setBusinessName(e.target.value)}
          />
        </div>
      )}

      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Email Address</label>
        <input 
          type="email" 
          required
          className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-none outline-none focus:ring-2 ring-primary-500 transition-all font-bold"
          placeholder="admin@example.com"
          value={email}
          onChange={e => setEmail(e.target.value)}
        />
      </div>

      <div className="space-y-2">
        <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Password</label>
        <input 
          type="password" 
          required
          minLength={6}
          className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-none outline-none focus:ring-2 ring-primary-500 transition-all font-bold"
          placeholder="••••••••"
          value={pass}
          onChange={e => setPass(e.target.value)}
        />
      </div>

      <button 
        type="submit" 
        disabled={loading}
        className="w-full bg-primary-600 hover:bg-primary-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-black py-5 rounded-2xl shadow-2xl shadow-primary-500/30 flex items-center justify-center gap-3 group transition-all uppercase text-xs tracking-[0.2em] mt-4"
      >
        {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : (
          <>
            {isLogin ? 'Log In' : 'Create Profile'} 
            <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
          </>
        )}
      </button>
    </form>

    <div className="mt-8 text-center">
      <button 
        onClick={() => { setIsLogin(!isLogin); setErrorMsg(null); setInfoMsg(null); }}
        className="text-[10px] font-black text-primary-600 hover:text-primary-700 transition-colors uppercase tracking-[0.2em]"
      >
        {isLogin ? 'Establish New Profile' : 'Existing Profile Login'}
      </button>
    </div>

    <div className="mt-10 pt-8 border-t border-slate-100 dark:border-slate-800 flex items-center justify-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest">
      <ShieldCheck className="w-4 h-4 text-emerald-500" /> 
      Verified Secure Session
    </div>
  </div>
</div>

{/* Main Stats Cards */}
  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
    {cards.map((card, i) => (
      <div key={i} className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] shadow-sm border border-slate-200 dark:border-slate-800 transition-all hover:shadow-xl hover:-translate-y-1">
        <div className="flex justify-between items-start mb-8">
          <div className={`${card.color} p-5 rounded-2xl shadow-lg shadow-black/10`}>
            {card.icon}
          </div>
        </div>
        <div>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{card.title}</p>
          <h2 className="text-4xl font-black mt-3 text-slate-900 dark:text-white">
            ৳ {card.amount.toLocaleString('en-IN')}
          </h2>
        </div>
      </div>
    ))}
  </div>
</div>
{showAdd && (
