      <input placeholder="পণ্যের নাম" required className="bg-slate-50 dark:bg-slate-800 p-2.5 rounded-xl border-none outline-none focus:ring-2 ring-primary-500" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
      <input placeholder="SKU/কোড" className="bg-slate-50 dark:bg-slate-800 p-2.5 rounded-xl border-none outline-none focus:ring-2 ring-primary-500" value={form.sku} onChange={e => setForm({...form, sku: e.target.value})} />
      <input type="number" placeholder="ক্রয় মূল্য" required className="bg-slate-50 dark:bg-slate-800 p-2.5 rounded-xl border-none outline-none focus:ring-2 ring-primary-500" value={form.buying_price} onChange={e => setForm({...form, buying_price: Number(e.target.value)})} />
      <input type="number" placeholder="বিক্রয় মূল্য" required className="bg-slate-50 dark:bg-slate-800 p-2.5 rounded-xl border-none outline-none focus:ring-2 ring-primary-500" value={form.selling_price} onChange={e => setForm({...form, selling_price: Number(e.target.value)})} />
      <input type="number" placeholder="স্টক পরিমাণ" required className="bg-slate-50 dark:bg-slate-800 p-2.5 rounded-xl border-none outline-none focus:ring-2 ring-primary-500" value={form.stock} onChange={e => setForm({...form, stock: Number(e.target.value)})} />
      <button type="submit" className="bg-emerald-600 text-white py-2.5 rounded-xl font-bold hover:bg-emerald-700">সেভ করুন</button>
    </form>
  )}

  <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 overflow-hidden">
    <table className="w-full text-left">
      <thead className="bg-slate-50 dark:bg-slate-800 text-slate-500 text-xs uppercase font-bold">
        <tr>
          <th className="px-6 py-4">পণ্যের নাম</th>
          <th className="px-6 py-4">SKU</th>
          <th className="px-6 py-4 text-right">ক্রয় মূল্য</th>
          <th className="px-6 py-4 text-right">বিক্রয় মূল্য</th>
          <th className="px-6 py-4 text-right">স্টক</th>
        </tr>
      </thead>
      <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
        {products.length === 0 ? (
          <tr><td colSpan={5} className="px-6 py-12 text-center text-slate-400">কোন পণ্য পাওয়া যায়নি</td></tr>
        ) : products.map(p => (
          <tr key={p.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/30">
            <td className="px-6 py-4 font-medium">{p.name}</td>
            <td className="px-6 py-4 text-slate-500">{p.sku}</td>
            <td className="px-6 py-4 text-right">৳{p.buying_price}</td>
            <td className="px-6 py-4 text-right">৳{p.selling_price}</td>
            <td className={`px-6 py-4 text-right font-bold ${p.stock < 5 ? 'text-red-500' : 'text-emerald-500'}`}>{p.stock}</td>
          </tr>
        ))}
      </tbody>
    </table>
  </div>
</div>
{/* Sidebar */}
  <aside className={`
    fixed inset-y-0 left-0 z-50 w-72 bg-white dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800 transition-transform md:relative md:translate-x-0 no-print
    ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
  `}>
    <div className="p-6 h-full flex flex-col overflow-hidden">
      <div className="hidden md:flex items-center gap-2 font-black text-xl text-slate-900 dark:text-white mb-10 tracking-tighter">
        <Landmark className="w-6 h-6 text-primary-600" />
        <span className="truncate leading-none">EMBRODERY<br/><span className="text-sm font-bold text-slate-400">STATEMENT</span></span>
      </div>

      <nav className="flex-shrink-0 space-y-1 mb-8">
        {navItems.map(item => (
          <button
