          {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
          <span>{isDarkMode ? 'Light Mode' : 'Dark Mode'}</span>
        </button>
        <button onClick={logout} className="w-full flex items-center gap-3 px-4 py-2 rounded-lg hover:bg-red-50 text-red-600 dark:hover:bg-red-900/10 transition-colors text-xs font-bold">
          <LogOut className="w-4 h-4" />
          <span>Sign Out</span>
        </button>
      </div>
    </div>
  </aside>

  <main className="flex-1 overflow-x-hidden p-4 md:p-10">
    {children}
  </main>

  {isSidebarOpen && (
    <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />
  )}
</div>
const sortedTxs = [...transactions].sort((a, b) => 
  new Date(a.date).getTime() - new Date(b.date).getTime()
);

const entries = sortedTxs.map(t => {
  // Credit increases the customer debt (+), Payment decreases it (-)
  balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
  tCredit += (Number(t.credit) || 0);
  tPayment += (Number(t.payment) || 0);
  return { ...t, running_balance: balance } as LedgerEntry;
});

return { 
  ledgerEntries: entries, 
  totalCredit: tCredit, 
  totalPayment: tPayment, 
  finalBalance: balance 
};
{/* Professional Memo Container */}
