-- EMBRODERY STATEMENT Ledger App SQL Schema
-- এটি আপনার Supabase SQL Editor-এ রান করুন

-- ১. Parties টেবিল (কাস্টমার বা পার্টি লিস্ট)
CREATE TABLE IF NOT EXISTS "Parties" (
id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
name TEXT NOT NULL,
phone TEXT,
address TEXT,
user_id UUID NOT NULL DEFAULT auth.uid(),
created_at TIMESTAMPTZ DEFAULT now()
);

-- ২. Transactions টেবিল (লেনদেনের হিসাব)
CREATE TABLE IF NOT EXISTS "Transactions" (
id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
party_id UUID REFERENCES "Parties"(id) ON DELETE CASCADE,
date DATE NOT NULL DEFAULT CURRENT_DATE,
bill_no TEXT,
credit NUMERIC DEFAULT 0,
payment NUMERIC DEFAULT 0,
user_id UUID NOT NULL DEFAULT auth.uid(),
created_at TIMESTAMPTZ DEFAULT now()
);

-- ৩. Products টেবিল (ইনভেন্টরি বা মালামাল)
CREATE TABLE IF NOT EXISTS "Products" (
id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
name TEXT NOT NULL,
sku TEXT,
buying_price NUMERIC DEFAULT 0,
selling_price NUMERIC DEFAULT 0,
stock INTEGER DEFAULT 0,
user_id UUID NOT NULL DEFAULT auth.uid()
);

-- ৪. Sales টেবিল (সরাসরি বিক্রি)
CREATE TABLE IF NOT EXISTS "Sales" (
id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
date DATE NOT NULL DEFAULT CURRENT_DATE,
customer_name TEXT,
total_amount NUMERIC DEFAULT 0,
paid_amount NUMERIC DEFAULT 0,
user_id UUID NOT NULL DEFAULT auth.uid()
);

-- ৫. Expenses টেবিল (খরচের হিসাব)
CREATE TABLE IF NOT EXISTS "Expenses" (
id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
date DATE NOT NULL DEFAULT CURRENT_DATE,
category TEXT,
amount NUMERIC DEFAULT 0,
description TEXT,
user_id UUID NOT NULL DEFAULT auth.uid()
);

-- Row Level Security (RLS) এনাবল করা (যাতে একজন ইউজার অন্য ইউজারের ডাটা না দেখে)
ALTER TABLE "Parties" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Transactions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Products" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Sales" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "Expenses" ENABLE ROW LEVEL SECURITY;

-- সিকিউরিটি পলিসি সেটআপ (শুধুমাত্র নিজের ডাটা দেখা ও এডিট করা যাবে)

-- Parties Policies
CREATE POLICY "Users can manage their own parties" ON "Parties" FOR ALL USING (auth.uid() = user_id);

-- Transactions Policies
CREATE POLICY "Users can manage their own transactions" ON "Transactions" FOR ALL USING (auth.uid() = user_id);

-- Products Policies
CREATE POLICY "Users can manage their own products" ON "Products" FOR ALL USING (auth.uid() = user_id);

-- Sales Policies
CREATE POLICY "Users can manage their own sales" ON "Sales" FOR ALL USING (auth.uid() = user_id);

-- Expenses Policies
CREATE POLICY "Users can manage their own expenses" ON "Expenses" FOR ALL USING (auth.uid() = user_id);
