const Ledger: React.FC<LedgerProps> = ({ parties, selectedParty, transactions, user, onAddParty, onAddTransaction }) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<'credit' | 'payment'>('credit');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    await onAddParty(partyName, partyPhone);
    setPartyName('');
    setPartyPhone('');
    setShowPartyForm(false);
    setIsSubmitting(false);
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty) return;
    setIsSubmitting(true);
    await onAddTransaction({
      party_id: selectedParty.id,
      date,
      bill_no: billNo || 'N/A',
      credit: type === 'credit' ? Number(amount) : 0,
      payment: type === 'payment' ? Number(amount) : 0,
    });
    setAmount('');
    setBillNo('');
    setIsSubmitting(false);
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
      new Date(a.date).getTime() - new Date(b.date).getTime()
    );

    const entries = sortedTxs.map(t => {
      balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
      tCredit += (Number(t.credit) || 0);
      tPayment += (Number(t.payment) || 0);
      return { ...t, running_balance: balance };
    });

    return { entries, tCredit, tPayment, finalBalance: balance };
  };

  const { entries, tCredit, tPayment, finalBalance } = calculateLedger();

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 animate-in fade-in duration-500">
      <div className="xl:col-span-1 space-y-8">
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
