import React, { useState } from 'react';
import { Landmark, Dashboard as DashboardIcon, FileText, Package, ShoppingCart, Receipt, Search, Sun, Moon, LogOut, Menu, X } from 'lucide-react';
import { Party, TabType } from '../types';

interface SidebarProps {
  activeTab: TabType;
  setActiveTab: (t: TabType) => void;
  parties: Party[];
  selectedParty: Party | null;
  setSelectedParty: (p: Party) => void;
  isDarkMode: boolean;
  toggleDarkMode: () => void;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, parties, selectedParty, setSelectedParty, isDarkMode, toggleDarkMode, onLogout }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isOpen, setIsOpen] = useState(false);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <Landmark className="w-5 h-5" /> },
    { id: 'ledger', label: 'Ledger', icon: <FileText className="w-5 h-5" /> },
    { id: 'inventory', label: 'Inventory', icon: <Package className="w-5 h-5" /> },
    { id: 'sales', label: 'Sales', icon: <ShoppingCart className="w-5 h-5" /> },
    { id: 'expenses', label: 'Expenses', icon: <Receipt className="w-5 h-5" /> },
  ];

  const filteredParties = parties.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    p.phone.includes(searchTerm)
  );

  return (
    <>
      <button onClick={() => setIsOpen(true)} className="md:hidden fixed top-4 left-4 z-50 p-2 bg-white dark:bg-slate-900 rounded-lg shadow-lg">
        <Menu className="w-6 h-6" />
      </button>

      <aside className={`fixed inset-y-0 left-0 z-50 w-72 bg-white dark:bg-slate-900 border-r border-slate-200 dark:border-slate-800 transition-transform duration-300 md:relative md:translate-x-0 no-print ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 h-full flex flex-col overflow-hidden">
          <div className="flex items-center justify-between mb-10">
            <div className="flex items-center gap-3 font-black text-xl text-slate-900 dark:text-white tracking-tighter">
              <div className="p-2 bg-primary-600 rounded-xl">
                <Landmark className="w-6 h-6 text-white" />
              </div>
              <span className="leading-none uppercase">EMBRODERY<br/><span className="text-xs font-bold text-slate-400">STATEMENT</span></span>
            </div>
            <button onClick={() => setIsOpen(false)} className="md:hidden p-1">
              <X className="w-5 h-5" />
            </button>
          </div>

          <nav className="flex-shrink-0 space-y-1 mb-8">
            {navItems.map(item => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id as TabType); setIsOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm transition-all ${
                  activeTab === item.id 
                  ? 'bg-primary-600 text-white shadow-lg shadow-primary-500/30 font-bold' 
                  : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'
                }`}
              >
                {item.icon}
                <span className="uppercase text-[10px] font-black tracking-widest">{item.label}</span>
              </button>
            ))}
