          <div className="flex-1 flex flex-col min-h-0 border-t border-slate-100 dark:border-slate-800 pt-6">
            <div className="flex items-center justify-between mb-4 px-2">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Client Parties</h3>
            </div>

            <div className="relative mb-3 px-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" />
              <input 
                type="text" 
                placeholder="Find party..." 
                className="w-full bg-slate-50 dark:bg-slate-800/50 border-none text-[10px] font-bold p-3 pl-9 rounded-xl outline-none focus:ring-1 ring-primary-500"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <div className="flex-1 overflow-y-auto pr-2 space-y-1 scrollbar-thin">
              {filteredParties.map(party => (
                <button
                  key={party.id}
                  onClick={() => { setSelectedParty(party); setActiveTab('ledger'); setIsOpen(false); }}
                  className={`w-full flex flex-col items-start gap-1 px-4 py-3 rounded-xl text-xs text-left transition-all ${
                    selectedParty?.id === party.id 
                    ? 'bg-primary-50 dark:bg-primary-900/20 text-primary-600 font-bold border-l-4 border-primary-500' 
                    : 'hover:bg-slate-50 dark:hover:bg-slate-800/50 text-slate-500 dark:text-slate-400'
                  }`}
                >
                  <span className="truncate w-full font-black uppercase text-[9px] tracking-tight">{party.name}</span>
                  <span className="text-[9px] opacity-70 font-mono tracking-tighter">{party.phone}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="mt-auto pt-6 border-t border-slate-200 dark:border-slate-800 space-y-2">
            <button onClick={toggleDarkMode} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-[10px] font-black uppercase tracking-widest">
              {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              <span>{isDarkMode ? 'Light Mode' : 'Dark Mode'}</span>
            </button>
            <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 dark:hover:bg-red-900/10 transition-colors text-[10px] font-black uppercase tracking-widest">
              <LogOut className="w-4 h-4" />
              <span>Sign Out</span>
            </button>
          </div>
        </div>
      </aside>

      {isOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsOpen(false)} />
      )}
    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { Landmark, ArrowRight, Loader2, AlertCircle, ShieldCheck } from 'lucide-react';

interface AuthProps {
  onLogin: (email: string, pass: string) => Promise<any>;
  onSignup: (email: string, pass: string, biz: string) => Promise<any>;
}

const Auth: React.FC<AuthProps> = ({ onLogin, onSignup }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [pass, setPass] = useState('');
  const [businessName, setBusinessName] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [infoMsg, setInfoMsg] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setErrorMsg(null);
    setInfoMsg(null);

    try {
      if (isLogin) {
        const res = await onLogin(email, pass);
        if (!res.success) setErrorMsg(res.message || 'Login failed');
      } else {
        const res = await onSignup(email, pass, businessName);
        if (!res.success) {
          setErrorMsg(res.message || 'Signup failed');
        } else if (res.message) {
          setInfoMsg(res.message);
        }
      }
    } catch (err) {
      setErrorMsg('An unexpected error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-50 dark:bg-slate-950 font-sans">
      <div className="w-full max-w-md">
        <div className="text-center mb-10 animate-in fade-in slide-in-from-top-4 duration-700">
          <div className="inline-flex p-4 bg-primary-600 rounded-[2rem] shadow-2xl shadow-primary-500/40 mb-6">
            <Landmark className="w-10 h-10 text-white" />
          </div>
          <h1 className="text-4xl font-black text-slate-900 dark:text-white uppercase tracking-tighter">Embrodery Statement</h1>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.4em] mt-3">Professional Ledger Workspace</p>
        </div>

        <div className="bg-white dark:bg-slate-900 p-8 md:p-10 rounded-[2.5rem] shadow-2xl shadow-black/5 border border-slate-100 dark:border-slate-800 animate-in fade-in zoom-in-95 duration-500">
          {errorMsg && (
            <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-800 rounded-2xl flex items-start gap-3 text-red-600 dark:text-red-400 text-sm">
              <AlertCircle className="w-5 h-5 flex-shrink-0" />
              <p className="font-bold leading-tight">{errorMsg}</p>
            </div>
          )}

          {infoMsg && (
            <div className="mb-6 p-4 bg-emerald-50 dark:bg-emerald-900/10 border border-emerald-200 dark:border-emerald-800 rounded-2xl flex items-start gap-3 text-emerald-600 dark:text-emerald-400 text-sm">
              <ShieldCheck className="w-5 h-5 flex-shrink-0" />
              <p className="font-bold leading-tight">{infoMsg}</p>
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-5">
            {!isLogin && (
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Business Name</label>
                <input type="text" required className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-none outline-none focus:ring-2 ring-primary-500 transition-all font-bold" placeholder="e.g. Skyline Designs" value={businessName} onChange={e => setBusinessName(e.target.value)} />
              </div>
            )}

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Email Address</label>
              <input type="email" required className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-none outline-none focus:ring-2 ring-primary-500 transition-all font-bold" placeholder="admin@example.com" value={email} onChange={e => setEmail(e.target.value)} />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Password</label>
              <input type="password" required minLength={6} className="w-full bg-slate-50 dark:bg-slate-800 p-4 rounded-2xl border-none outline-none focus:ring-2 ring-primary-500 transition-all font-bold" placeholder="••••••••" value={pass} onChange={e => setPass(e.target.value)} />
            </div>

            <button type="submit" disabled={loading} className="w-full bg-primary-600 hover:bg-primary-700 disabled:opacity-50 text-white font-black py-5 rounded-2xl shadow-2xl shadow-primary-500/30 flex items-center justify-center gap-3 group transition-all uppercase text-xs tracking-[0.2em] mt-4">
              {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : (
                <>{isLogin ? 'Log In' : 'Create Profile'} <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" /></>
              )}
            </button>
