import { supabase } from './supabaseClient';
import { Party, Transaction, Product, Expense, Sale } from '../types';

const isConfigured = () => {
  return !supabase.supabaseUrl.includes('placeholder-project.supabase.co');
};

export const dbService = {
  login: async (email: string, pass: string) => {
    if (!isConfigured()) return { success: false, message: 'Supabase configuration is missing.' };

    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password: pass,
    });
    if (error) return { success: false, message: error.message };

    const user = {
      id: data.user.id,
      email: data.user.email!,
      business_name: data.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
    };
    return { success: true, user };
  },

  signup: async (email: string, pass: string, businessName: string) => {
    if (!isConfigured()) return { success: false, message: 'Supabase configuration is missing.' };

    const { data, error } = await supabase.auth.signUp({
      email,
      password: pass,
      options: {
        data: {
          business_name: businessName,
        }
      }
    });
    if (error) return { success: false, message: error.message };

    if (data.user && !data.session) {
      return { success: true, message: 'Signup successful! Please check your email for verification.' };
    }

    const user = {
      id: data.user!.id,
      email: data.user!.email!,
      business_name: businessName
    };
    return { success: true, user };
  },

  logout: async () => {
    if (isConfigured()) {
      await supabase.auth.signOut();
    }
  },

  getInitialData: async () => {
    if (!isConfigured()) return { parties: [], transactions: [], products: [], expenses: [], sales: [] };

    const [parties, txs, products, expenses, sales] = await Promise.all([
      supabase.from('Parties').select('*'),
      supabase.from('Transactions').select('*'),
      supabase.from('Products').select('*'),
      supabase.from('Expenses').select('*'),
      supabase.from('Sales').select('*'),
    ]);

    return {
      parties: parties.data || [],
      transactions: txs.data || [],
      products: products.data || [],
      expenses: expenses.data || [],
      sales: sales.data || []
    };
  },

  addParty: async (party: Omit<Party, 'id' | 'created_at'>) => {
    if (!isConfigured()) throw new Error('Supabase not configured');
    const { data, error } = await supabase.from('Parties').insert([party]).select();
    if (error) throw error;
    return data[0];
  },

  addTransaction: async (tx: Omit<Transaction, 'id' | 'created_at'>) => {
    if (!isConfigured()) throw new Error('Supabase not configured');
    const { data, error } = await supabase.from('Transactions').insert([tx]).select();
    if (error) throw error;
    return data[0];
  },

  addProduct: async (p: Omit<Product, 'id'>) => {
    if (!isConfigured()) throw new Error('Supabase not configured');
    const { data, error } = await supabase.from('Products').insert([p]).select();
    if (error) throw error;
    return data[0];
  },

  addExpense: async (e: Omit<Expense, 'id'>) => {
    if (!isConfigured()) throw new Error('Supabase not configured');
    const { data, error } = await supabase.from('Expenses').insert([e]).select();
    if (error) throw error;
    return data[0];
  },

  addSale: async (s: Omit<Sale, 'id'>) => {
    if (!isConfigured()) throw new Error('Supabase not configured');
    const { data, error } = await supabase.from('Sales').insert([s]).select();
    if (error) throw error;
    return data[0];
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Landmark, AlertTriangle } from 'lucide-react';
import { Party, Transaction, Product, Expense, Sale, User, TabType } from './types';
import { dbService } from './services/supabaseService';
import { supabase } from './services/supabaseClient';
import Auth from './components/Auth';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Ledger from './components/Ledger';
import Inventory from './components/Inventory';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>('dashboard');
  const [parties, setParties] = useState<Party[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [selectedParty, setSelectedParty] = useState<Party | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [loading, setLoading] = useState(true);
  const [isMisconfigured, setIsMisconfigured] = useState(false);

  const [stats, setStats] = useState({
    totalCredit: 0,
    totalCollected: 0,
    totalOutstanding: 0,
    totalSales: 0,
    totalExpenses: 0,
    inventoryValue: 0
  });

  const refreshData = useCallback(async () => {
    if (!user) return;
    try {
      const db = await dbService.getInitialData();
      setParties(db.parties);
      setProducts(db.products);
      setSales(db.sales);
      setExpenses(db.expenses);
      setTransactions(db.transactions);

      const totalCredit = db.transactions.reduce((sum, item) => sum + (Number(item.credit) || 0), 0);
      const totalCollected = db.transactions.reduce((sum, item) => sum + (Number(item.payment) || 0), 0);
      const totalSales = db.sales.reduce((sum, item) => sum + (Number(item.total_amount) || 0), 0);
      const totalExpenses = db.expenses.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
      const inventoryValue = db.products.reduce((sum, item) => sum + ((Number(item.buying_price) || 0) * (Number(item.stock) || 0)), 0);

      setStats({
        totalCredit,
        totalCollected,
        totalOutstanding: totalCredit - totalCollected,
        totalSales,
        totalExpenses,
        inventoryValue
      });
    } catch (err) {
      console.error('Failed to fetch data:', err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    // Check for misconfiguration on mount
    const isPlaceholder = supabase.supabaseUrl.includes('placeholder-project.supabase.co');
    if (isPlaceholder) {
      setIsMisconfigured(true);
      setLoading(false);
      return;
    }

    // 1. Initial Session Check
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          business_name: session.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
        });
      } else {
        setLoading(false);
      }
    });

    // 2. Auth Change Listener
    const { data: { subscription: authSub } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          business_name: session.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
        });
      } else {
        setUser(null);
        setParties([]);
        setTransactions([]);
        setProducts([]);
        setStats({
          totalCredit: 0,
          totalCollected: 0,
          totalOutstanding: 0,
          totalSales: 0,
          totalExpenses: 0,
          inventoryValue: 0
        });
      }
    });

    return () => authSub.unsubscribe();
  }, []);

  useEffect(() => {
    if (user && !isMisconfigured) {
      refreshData();

      // 3. Real-time Database Subscription
      const channel = supabase
        .channel('db_changes')
        .on('postgres_changes', { event: '*', schema: 'public' }, () => {
          refreshData();
        })
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [user, refreshData, isMisconfigured]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogin = async (e: string, p: string) => {
    const res = await dbService.login(e, p);
    return res;
  };

  const handleSignup = async (e: string, p: string, b: string) => {
    const res = await dbService.signup(e, p, b);
    return res;
  };

  const handleLogout = async () => {
    await dbService.logout();
    setUser(null);
  };

  const handleAddParty = async (name: string, phone: string) => {
    await dbService.addParty({ name, phone });
  };

  const handleAddTransaction = async (data: Omit<Transaction, 'id' | 'created_at'>) => {
    await dbService.addTransaction(data);
  };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    await dbService.addProduct(p);
  };

  if (loading && !user && !isMisconfigured) {
    return (
      <div className="h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (isMisconfigured) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl border border-rose-100 dark:border-rose-900/30 text-center">
          <div className="inline-flex p-5 bg-rose-50 dark:bg-rose-900/20 rounded-full mb-6">
            <AlertTriangle className="w-10 h-10 text-rose-500" />
          </div>
          <h1 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight mb-4">Configuration Required</h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-8">
            The Supabase backend is not configured. Please set the following environment variables in your project settings:
            <div className="mt-4 space-y-2 text-left bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl font-mono text-xs">
              <div className="flex justify-between">
                <span className="text-slate-400">Variable</span>
                <span className="text-slate-400">Status</span>
              </div>
              <div className="flex justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                <span className="text-rose-500">SUPABASE_URL</span>
                <span className="text-rose-500 italic">Missing</span>
              </div>
              <div className="flex justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                <span className="text-rose-500">SUPABASE_ANON_KEY</span>
                <span className="text-rose-500 italic">Missing</span>
              </div>
            </div>
          </p>
          <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-loose">
              Once configured, the app will enable cloud sync and authentication.
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Auth onLogin={handleLogin} onSignup={handleSignup} />;
  }

  return (
    <div className="flex h-screen overflow-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        parties={parties}
        selectedParty={selectedParty}
        setSelectedParty={setSelectedParty}
        isDarkMode={isDarkMode}
        toggleDarkMode={() => setIsDarkMode(!isDarkMode)}
        onLogout={handleLogout}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-10 no-print">
        {activeTab === 'dashboard' && <Dashboard stats={stats} />}
        {activeTab === 'ledger' && (
          <Ledger 
            parties={parties} 
            selectedParty={selectedParty} 
            transactions={selectedParty ? transactions.filter(t => t.party_id === selectedParty.id) : []}
            user={user}
            onAddParty={handleAddParty}
            onAddTransaction={handleAddTransaction}
          />
        )}
        {activeTab === 'inventory' && (
          <Inventory 
            products={products}
            onAddProduct={handleAddProduct}
          />
        )}
        {['sales', 'expenses'].includes(activeTab) && (
          <div className="h-full flex flex-col items-center justify-center text-center py-20 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-200 dark:border-slate-800">
             <Landmark className="w-12 h-12 text-slate-300 mb-6" />
             <h2 className="text-xl font-black uppercase tracking-widest text-slate-400">Coming Soon</h2>
             <p className="text-xs text-slate-500 mt-2">Enhanced {activeTab} modules are under development.</p>
          </div>
        )}
      </main>

      {/* Print View Mirror */}
      <div className="hidden print:block fixed inset-0 bg-white z-[100] p-0 overflow-visible">
         {activeTab === 'ledger' && selectedParty && (
           <Ledger 
              parties={parties} 
              selectedParty={selectedParty} 
              transactions={transactions.filter(t => t.party_id === selectedParty.id)}
              user={user}
              onAddParty={handleAddParty}
              onAddTransaction={handleAddTransaction}
            />
         )}
      </div>
    </div>
  );
};

