      const totalExpenses = db.expenses.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
      const inventoryValue = db.products.reduce((sum, item) => sum + ((Number(item.buying_price) || 0) * (Number(item.stock) || 0)), 0);

      setStats({
        totalCredit,
        totalCollected,
        totalOutstanding: totalCredit - totalCollected,
        totalSales,
        totalExpenses,
        inventoryValue
      });
    } catch (err) {
      console.error('Failed to fetch data:', err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    // Check for misconfiguration on mount using exported supabaseUrl to avoid protected property access
    const isPlaceholder = supabaseUrl.includes('placeholder-project.supabase.co');
    if (isPlaceholder) {
      setIsMisconfigured(true);
      setLoading(false);
      return;
    }

    // 1. Initial Session Check
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          business_name: session.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
        });
      } else {
        setLoading(false);
      }
    });

    // 2. Auth Change Listener
    const { data: { subscription: authSub } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          business_name: session.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
        });
      } else {
        setUser(null);
        setParties([]);
        setTransactions([]);
        setProducts([]);
        setStats({
          totalCredit: 0,
          totalCollected: 0,
          totalOutstanding: 0,
          totalSales: 0,
          totalExpenses: 0,
          inventoryValue: 0
        });
      }
    });

    return () => authSub.unsubscribe();
  }, []);

  useEffect(() => {
    if (user && !isMisconfigured) {
      refreshData();

      // 3. Real-time Database Subscription
      const channel = supabase
        .channel('db_changes')
        .on('postgres_changes', { event: '*', schema: 'public' }, () => {
          refreshData();
        })
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [user, refreshData, isMisconfigured]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogin = async (e: string, p: string) => {
    const res = await dbService.login(e, p);
    return res;
  };

  const handleSignup = async (e: string, p: string, b: string) => {
    const res = await dbService.signup(e, p, b);
    return res;
  };

  const handleLogout = async () => {
    await dbService.logout();
    setUser(null);
  };

  const handleAddParty = async (name: string, phone: string) => {
    try {
      await dbService.addParty({ name, phone });
      await refreshData();
    } catch (err: any) {
      alert(`Error adding party: ${err.message || 'Unknown error'}`);
    }
  };

  const handleAddTransaction = async (data: Omit<Transaction, 'id' | 'created_at'>) => {
    try {
      await dbService.addTransaction(data);
      await refreshData();
    } catch (err: any) {
      alert(`Error adding transaction: ${err.message || 'Unknown error'}`);
    }
  };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    try {
      await dbService.addProduct(p);
      await refreshData();
    } catch (err: any) {
      alert(`Error adding product: ${err.message || 'Unknown error'}`);
    }
  };

  if (loading && !user && !isMisconfigured) {
    return (
      <div className="h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (isMisconfigured) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl border border-rose-100 dark:border-rose-900/30 text-center">
          <div className="inline-flex p-5 bg-rose-50 dark:bg-rose-900/20 rounded-full mb-6">
            <AlertTriangle className="w-10 h-10 text-rose-500" />
          </div>
          <h1 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight mb-4">Configuration Required</h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-8">
            The Supabase backend is not configured. Please set the following environment variables in your project settings:
            <div className="mt-4 space-y-2 text-left bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl font-mono text-xs">
              <div className="flex justify-between">
                <span className="text-slate-400">Variable</span>
                <span className="text-slate-400">Status</span>
              </div>
              <div className="flex justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                <span className="text-rose-500">SUPABASE_URL</span>
                <span className="text-rose-500 italic">Missing</span>
              </div>
              <div className="flex justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                <span className="text-rose-500">SUPABASE_ANON_KEY</span>
                <span className="text-rose-500 italic">Missing</span>
              </div>
            </div>
          </p>
          <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-loose">
              Once configured, the app will enable cloud sync and authentication.
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Auth onLogin={handleLogin} onSignup={handleSignup} />;
  }

  return (
    <div className="flex h-screen overflow-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        parties={parties}
        selectedParty={selectedParty}
        setSelectedParty={setSelectedParty}
        isDarkMode={isDarkMode}
        toggleDarkMode={() => setIsDarkMode(!isDarkMode)}
        onLogout={handleLogout}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-10 no-print">
        {activeTab === 'dashboard' && <Dashboard stats={stats} user={user} />}
        {activeTab === 'ledger' && (
          <Ledger 
            parties={parties} 
            selectedParty={selectedParty} 
            transactions={selectedParty ? transactions.filter(t => t.party_id === selectedParty.id) : []}
            user={user}
            onAddParty={handleAddParty}
            onAddTransaction={handleAddTransaction}
          />
        )}
        {activeTab === 'inventory' && (
          <Inventory 
            products={products}
            onAddProduct={handleAddProduct}
          />
        )}
        {['sales', 'expenses'].includes(activeTab) && (
          <div className="h-full flex flex-col items-center justify-center text-center py-20 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-200 dark:border-slate-800">
             <Landmark className="w-12 h-12 text-slate-300 mb-6" />
             <h2 className="text-xl font-black uppercase tracking-widest text-slate-400">Coming Soon</h2>
             <p className="text-xs text-slate-500 mt-2">Enhanced {activeTab} modules are under development.</p>
          </div>
        )}
      </main>

      {/* Print View Mirror */}
      <div className="hidden print:block fixed inset-0 bg-white z-[100] p-0 overflow-visible">
         {activeTab === 'ledger' && selectedParty && (
           <Ledger 
              parties={parties} 
              selectedParty={selectedParty} 
              transactions={transactions.filter(t => t.party_id === selectedParty.id)}
              user={user}
              onAddParty={handleAddParty}
              onAddTransaction={handleAddTransaction}
            />
         )}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, Plus, ReceiptText, UserPlus, Search, FileText } from 'lucide-react';
import { Party, Transaction, User as UserType } from '../types';

interface LedgerProps {
  parties: Party[];
  selectedParty: Party | null;
  transactions: Transaction[];
  user: UserType | null;
  onAddParty: (name: string, phone: string) => Promise<void>;
  onAddTransaction: (data: Omit<Transaction, 'id' | 'created_at'>) => Promise<void>;
}

const Ledger: React.FC<LedgerProps> = ({ parties, selectedParty, transactions, user, onAddParty, onAddTransaction }) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<'credit' | 'payment'>('credit');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddParty(partyName, partyPhone);
      setPartyName('');
      setPartyPhone('');
      setShowPartyForm(false);
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddTransaction({
        party_id: selectedParty.id,
        date,
        bill_no: billNo || 'N/A',
        credit: type === 'credit' ? Number(amount) : 0,
        payment: type === 'payment' ? Number(amount) : 0,
      });
      setAmount('');
      setBillNo('');
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
      new Date(a.date).getTime() - new Date(b.date).getTime()
    );

    const entries = sortedTxs.map(t => {
      balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
      tCredit += (Number(t.credit) || 0);
      tPayment += (Number(t.payment) || 0);
      return { ...t, running_balance: balance };
    });

    return { entries, tCredit, tPayment, finalBalance: balance };
  };

  const { entries, tCredit, tPayment, finalBalance } = calculateLedger();

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 animate-in fade-in duration-500">
      <div className="xl:col-span-1 space-y-8">
        {/* Add Transaction Section */}
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-3 bg-primary-50 dark:bg-primary-900/20 rounded-xl">
              <ReceiptText className="w-5 h-5 text-primary-500" />
            </div>
            <h3 className="text-xl font-black tracking-tight">Add Transaction</h3>
          </div>

          {!selectedParty ? (
            <div className="py-12 px-6 text-center bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-dashed border-slate-200 dark:border-slate-700">
