                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Party Name</label>
                <input type="text" placeholder="Full Name" required value={partyName} onChange={e => setPartyName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Phone</label>
                <input type="tel" placeholder="01xxxxxxxxx" value={partyPhone} onChange={e => setPartyPhone(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowPartyForm(false)} className="flex-1 bg-slate-100 dark:bg-slate-800 py-4 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-colors">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="flex-1 bg-emerald-600 text-white font-black py-4 rounded-xl transition-all shadow-lg shadow-emerald-500/20 text-xs uppercase tracking-widest active:scale-95">
                  {isSubmitting ? 'Saving...' : 'Create'}
