              <div className="flex flex-col justify-end items-end">
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Net Balance</p>
                  <div className={`text-5xl font-black tracking-tighter ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                    ৳ {finalBalance.toLocaleString('en-IN')}
                  </div>
                </div>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="border-y-2 border-slate-900 dark:border-slate-100 bg-slate-50 dark:bg-slate-900/30">
                    <th className="py-5 px-4 text-left text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Date</th>
                    <th className="py-5 px-4 text-left text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Bill No</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Credit (+)</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Payment (-)</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white bg-slate-100 dark:bg-slate-900">Balance</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-900">
                  {entries.length === 0 ? (
                    <tr><td colSpan={5} className="py-24 text-center text-slate-400 font-bold text-xs uppercase tracking-widest">No entries found</td></tr>
                  ) : entries.map((entry) => (
                    <tr key={entry.id}>
                      <td className="py-5 px-4 text-xs font-mono">{new Date(entry.date).toLocaleDateString('en-GB')}</td>
                      <td className="py-5 px-4 text-sm font-bold text-slate-700 dark:text-slate-300">{entry.bill_no}</td>
                      <td className="py-5 px-4 text-right text-sm font-bold text-emerald-600 dark:text-emerald-400">{entry.credit > 0 ? entry.credit.toLocaleString('en-IN') : '-'}</td>
                      <td className="py-5 px-4 text-right text-sm font-bold text-rose-600 dark:text-rose-400">{entry.payment > 0 ? entry.payment.toLocaleString('en-IN') : '-'}</td>
                      <td className={`py-5 px-4 text-right text-sm font-black bg-slate-50/30 dark:bg-slate-900/10 ${entry.running_balance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{entry.running_balance.toLocaleString('en-IN')}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-slate-900 dark:border-slate-100 bg-slate-50 dark:bg-slate-900 font-black">
                    <td colSpan={2} className="py-6 px-4 text-[10px] uppercase tracking-[0.3em] text-slate-500">Statement Totals:</td>
                    <td className="py-6 px-4 text-right text-base text-emerald-600">{tCredit.toLocaleString('en-IN')}</td>
                    <td className="py-6 px-4 text-right text-base text-rose-600">{tPayment.toLocaleString('en-IN')}</td>
                    <td className={`py-6 px-4 text-right text-xl ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{finalBalance.toLocaleString('en-IN')}</td>
                  </tr>
                </tfoot>
              </table>
