          <nav className="flex-shrink-0 space-y-1 mb-8">
            {navItems.map(item => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id as TabType); setIsOpen(false); }}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm transition-all ${
                  activeTab === item.id 
                  ? 'bg-primary-600 text-white shadow-lg shadow-primary-500/30 font-bold' 
                  : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800'
                }`}
              >
                {item.icon}
                <span className="uppercase text-[10px] font-black tracking-widest">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="flex-1 flex flex-col min-h-0 border-t border-slate-100 dark:border-slate-800 pt-6">
            <div className="flex items-center justify-between mb-4 px-2">
              <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Client Parties</h3>
            </div>

            <div className="relative mb-3 px-1">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-400" />
              <input 
                type="text" 
                placeholder="Find party..." 
                className="w-full bg-slate-50 dark:bg-slate-800/50 border-none text-[10px] font-bold p-3 pl-9 rounded-xl outline-none focus:ring-1 ring-primary-500"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>

            <div className="flex-1 overflow-y-auto pr-2 space-y-1 scrollbar-thin">
              {filteredParties.map(party => (
                <div key={party.id} className="relative group">
                  <button
                    onClick={() => { setSelectedParty(party); setActiveTab('ledger'); setIsOpen(false); }}
                    onMouseDown={() => startLongPress(party.id)}
                    onMouseUp={cancelLongPress}
                    onMouseLeave={cancelLongPress}
                    onTouchStart={() => startLongPress(party.id)}
                    onTouchEnd={cancelLongPress}
                    className={`w-full flex flex-col items-start gap-1 px-4 py-3 rounded-xl text-xs text-left transition-all relative ${
                      selectedParty?.id === party.id 
                      ? 'bg-primary-50 dark:bg-primary-900/20 text-primary-600 font-bold border-l-4 border-primary-500' 
                      : 'hover:bg-slate-50 dark:hover:bg-slate-800/50 text-slate-500 dark:text-slate-400'
                    }`}
                  >
                    <span className="truncate w-full font-black uppercase text-[9px] tracking-tight">{party.name}</span>
                    <span className="text-[9px] opacity-70 font-mono tracking-tighter">{party.phone}</span>
                  </button>

                  {/* Desktop Actions Menu Toggle */}
                  <button 
                    onClick={(e) => { e.stopPropagation(); setActiveMenuId(activeMenuId === party.id ? null : party.id); }}
                    className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 opacity-0 group-hover:opacity-100 transition-opacity hidden md:block"
                  >
                    <MoreVertical className="w-3.5 h-3.5 text-slate-400" />
                  </button>

                  {/* Actions Popover with Animation */}
                  {activeMenuId === party.id && (
                    <div className="absolute right-0 top-1/2 -translate-y-1/2 z-[60] bg-white dark:bg-slate-800 shadow-2xl rounded-xl border border-slate-200 dark:border-slate-700 p-1 min-w-[120px] animate-in zoom-in-95 fade-in duration-200 origin-right">
                      <button onClick={() => handleEdit(party)} className="w-full flex items-center gap-2 px-3 py-2 text-[10px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg">
                        <Edit2 className="w-3 h-3" /> Edit
                      </button>
                      <button onClick={() => handleDelete(party.id)} className="w-full flex items-center gap-2 px-3 py-2 text-[10px] font-black uppercase tracking-widest text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-900/10 rounded-lg">
                        <Trash2 className="w-3 h-3" /> Delete
                      </button>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>

          <div className="mt-auto pt-6 border-t border-slate-200 dark:border-slate-800 space-y-2">
            <button onClick={toggleDarkMode} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors text-[10px] font-black uppercase tracking-widest">
              {isDarkMode ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
              <span>{isDarkMode ? 'Light Mode' : 'Dark Mode'}</span>
            </button>
            <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-3 rounded-xl hover:bg-red-50 text-red-600 dark:hover:bg-red-900/10 transition-colors text-[10px] font-black uppercase tracking-widest">
              <LogOut className="w-4 h-4" />
              <span>Sign Out</span>
            </button>
          </div>
        </div>
      </aside>

      {isOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsOpen(false)} />
      )}

      {/* Close Menu on Overlay Click */}
      {activeMenuId && (
        <div className="fixed inset-0 z-50 cursor-default" onClick={() => setActiveMenuId(null)} />
      )}
    </>
  );
};

export default Sidebar;

import React, { useState, useRef } from 'react';
import { User, Plus, ReceiptText, UserPlus, Search, FileText, MoreVertical, Edit2, Trash2 } from 'lucide-react';
import { Party, Transaction, User as UserType } from '../types';

interface LedgerProps {
  parties: Party[];
  selectedParty: Party | null;
  transactions: Transaction[];
  user: UserType | null;
  onAddParty: (name: string, phone: string) => Promise<void>;
  onAddTransaction: (data: Omit<Transaction, 'id' | 'created_at'>) => Promise<void>;
  onEditTransaction: (id: string, updates: Partial<Transaction>) => Promise<void>;
  onDeleteTransaction: (id: string) => Promise<void>;
}

const Ledger: React.FC<LedgerProps> = ({ 
  parties, selectedParty, transactions, user, onAddParty, 
  onAddTransaction, onEditTransaction, onDeleteTransaction 
}) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<'credit' | 'payment'>('credit');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeTxMenuId, setActiveTxMenuId] = useState<string | null>(null);
  const longPressTimer = useRef<number | null>(null);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddParty(partyName, partyPhone);
      setPartyName('');
      setPartyPhone('');
      setShowPartyForm(false);
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddTransaction({
        party_id: selectedParty.id,
        date,
        bill_no: billNo || 'N/A',
        credit: type === 'credit' ? Number(amount) : 0,
        payment: type === 'payment' ? Number(amount) : 0,
      });
      setAmount('');
      setBillNo('');
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEditTx = (tx: Transaction) => {
    const newDate = prompt('Enter new Date (YYYY-MM-DD):', tx.date);
    const newBill = prompt('Enter new Bill No:', tx.bill_no);
    if (newDate && newBill) {
      onEditTransaction(tx.id, { date: newDate, bill_no: newBill });
    }
    setActiveTxMenuId(null);
  };

  const handleDeleteTx = (id: string) => {
    onDeleteTransaction(id);
    setActiveTxMenuId(null);
  };

  const startLongPress = (id: string) => {
    longPressTimer.current = window.setTimeout(() => {
      setActiveTxMenuId(id);
    }, 600);
  };

  const cancelLongPress = () => {
    if (longPressTimer.current) {
      window.clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
      new Date(a.date).getTime() - new Date(b.date).getTime()
    );

    const entries = sortedTxs.map(t => {
      balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
      tCredit += (Number(t.credit) || 0);
      tPayment += (Number(t.payment) || 0);
      return { ...t, running_balance: balance };
    });

    return { entries, tCredit, tPayment, finalBalance: balance };
  };

  const { entries, tCredit, tPayment, finalBalance } = calculateLedger();

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 animate-in fade-in duration-500 relative">
      <div className="xl:col-span-1 space-y-8 no-print">
        {/* Add Transaction Section */}
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-3 bg-primary-50 dark:bg-primary-900/20 rounded-xl">
              <ReceiptText className="w-5 h-5 text-primary-500" />
            </div>
            <h3 className="text-xl font-black tracking-tight">Add Transaction</h3>
          </div>

          {!selectedParty ? (
            <div className="py-12 px-6 text-center bg-slate-50 dark:bg-slate-800/50 rounded-2xl border border-dashed border-slate-200 dark:border-slate-700">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                Select a <span className="text-primary-600">party</span> first
              </p>
            </div>
          ) : (
            <form onSubmit={handleTxSubmit} className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Date</label>
                  <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Bill No</label>
                  <input type="text" placeholder="B-101" value={billNo} onChange={e => setBillNo(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 font-bold">৳</span>
                  <input type="number" placeholder="0.00" required value={amount} onChange={e => setAmount(e.target.value)} className="w-full bg-slate-100 dark:bg-slate-800 border-none rounded-xl py-4 pl-9 pr-4 text-xl font-black focus:ring-2 focus:ring-primary-500 outline-none" />
                </div>
              </div>

              <div className="flex gap-2 p-1.5 bg-slate-100 dark:bg-slate-800 rounded-2xl">
                <button type="button" onClick={() => setType('credit')} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${type === 'credit' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600' : 'text-slate-500'}`}>Credit (+)</button>
                <button type="button" onClick={() => setType('payment')} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${type === 'payment' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-500'}`}>Payment (-)</button>
              </div>

              <button type="submit" disabled={isSubmitting} className={`w-full font-black py-4 rounded-2xl transition-all flex items-center justify-center gap-3 shadow-lg shadow-black/10 active:scale-95 uppercase text-xs tracking-[0.2em] ${type === 'credit' ? 'bg-primary-600 hover:bg-primary-700' : 'bg-emerald-600 hover:bg-emerald-700'} text-white`}>
                <Plus className="w-5 h-5" />
                {isSubmitting ? 'Saving...' : `Save ${type} Entry`}
              </button>
            </form>
          )}
        </div>

        {/* New Party Section */}
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="p-3 bg-emerald-50 dark:bg-emerald-900/20 rounded-xl">
                <UserPlus className="w-5 h-5 text-emerald-500" />
              </div>
              <h3 className="text-xl font-black tracking-tight">New Party</h3>
            </div>
            {!showPartyForm && (
              <button 
                onClick={() => setShowPartyForm(true)} 
                className="px-6 py-2.5 bg-emerald-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-500/20 active:scale-95"
              >
                Open
              </button>
            )}
          </div>

          {showPartyForm ? (
            <form onSubmit={handlePartySubmit} className="space-y-6 animate-in slide-in-from-top-2">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Party Name</label>
                <input type="text" placeholder="Full Name" required value={partyName} onChange={e => setPartyName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Phone</label>
                <input type="tel" placeholder="01xxxxxxxxx" value={partyPhone} onChange={e => setPartyPhone(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowPartyForm(false)} className="flex-1 bg-slate-100 dark:bg-slate-800 py-4 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-slate-200 transition-colors">Cancel</button>
                <button type="submit" disabled={isSubmitting} className="flex-1 bg-emerald-600 text-white font-black py-4 rounded-xl transition-all shadow-lg shadow-emerald-500/20 text-xs uppercase tracking-widest active:scale-95">
                  {isSubmitting ? 'Saving...' : 'Create'}
                </button>
              </div>
            </form>
          ) : (
            <div className="flex flex-col items-center justify-center py-16 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-3xl">
              <div className="w-20 h-20 bg-slate-50 dark:bg-slate-800/50 rounded-full flex items-center justify-center mb-6">
                <UserPlus className="w-8 h-8 text-slate-300" />
              </div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest max-w-[150px] leading-relaxed">
                Register a new client account
              </p>
            </div>
          )}
        </div>
      </div>

      <div className="xl:col-span-2">
        {!selectedParty ? (
          <div className="bg-white dark:bg-slate-900 h-full min-h-[500px] rounded-[3rem] border border-slate-200 dark:border-slate-800 flex flex-col items-center justify-center p-12 text-center no-print">
            <div className="w-24 h-24 bg-primary-50 dark:bg-primary-900/10 rounded-full flex items-center justify-center mb-8">
              <Search className="w-10 h-10 text-primary-500" />
            </div>
            <h2 className="text-3xl font-black text-slate-900 dark:text-white mb-4 tracking-tighter">No Party Selected</h2>
            <p className="text-slate-500 max-w-xs uppercase text-[10px] font-black tracking-widest leading-loose">
              Please choose a customer from the sidebar to view their full ledger and generate statements
            </p>
          </div>
        ) : (
          <div className="bg-white dark:bg-slate-950 p-10 md:p-16 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden ledger-container">
            <div className="flex flex-col md:flex-row justify-between items-start border-b-2 border-slate-900 dark:border-slate-100 pb-10 mb-10 gap-6">
              <div className="space-y-2">
                <h1 className="text-5xl font-black text-slate-900 dark:text-white uppercase tracking-tighter">
                  {user?.business_name || 'Business Ledger'}
                </h1>
                <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Official Business Statement</p>
              </div>
              <div className="text-right space-y-1 no-print">
                <button onClick={() => window.print()} className="mb-4 px-4 py-2 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                  <FileText className="w-4 h-4" /> Print Statement
                </button>
                <div className="flex items-center justify-end gap-2 text-slate-900 dark:text-white font-black text-sm uppercase">
                  <span>Date: {new Date().toLocaleDateString('en-GB')}</span>
                </div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mb-12">
              <div className="space-y-4">
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Customer Details</div>
                <div className="p-6 rounded-3xl border border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-900/50">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center">
                      <User className="w-6 h-6 text-slate-500" />
                    </div>
                    <div>
                      <h3 className="text-2xl font-black text-slate-900 dark:text-white">{selectedParty.name}</h3>
                      <p className="text-sm text-slate-500 font-mono tracking-tighter">{selectedParty.phone || 'Phone N/A'}</p>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex flex-col justify-end items-end">
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 px-1">Net Balance</p>
                  <div className={`text-5xl font-black tracking-tighter ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                    ৳ {finalBalance.toLocaleString('en-IN')}
                  </div>
                </div>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full border-collapse">
                <thead>
                  <tr className="border-y-2 border-slate-900 dark:border-slate-100 bg-slate-50 dark:bg-slate-900/30">
                    <th className="py-5 px-4 text-left text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Date</th>
                    <th className="py-5 px-4 text-left text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Bill No</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Credit (+)</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Payment (-)</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white bg-slate-100 dark:bg-slate-900">Balance</th>
                    <th className="py-5 px-4 text-center text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white no-print">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 dark:divide-slate-900">
                  {entries.length === 0 ? (
                    <tr><td colSpan={6} className="py-24 text-center text-slate-400 font-bold text-xs uppercase tracking-widest">No entries found</td></tr>
                  ) : entries.map((entry) => (
                    <tr 
                      key={entry.id} 
                      className="group relative"
                      onMouseDown={() => startLongPress(entry.id)}
                      onMouseUp={cancelLongPress}
                      onMouseLeave={cancelLongPress}
                      onTouchStart={() => startLongPress(entry.id)}
                      onTouchEnd={cancelLongPress}
                    >
                      <td className="py-5 px-4 text-xs font-mono">{new Date(entry.date).toLocaleDateString('en-GB')}</td>
                      <td className="py-5 px-4 text-sm font-bold text-slate-700 dark:text-slate-300">{entry.bill_no}</td>
                      <td className="py-5 px-4 text-right text-sm font-bold text-emerald-600 dark:text-emerald-400">{entry.credit > 0 ? entry.credit.toLocaleString('en-IN') : '-'}</td>
                      <td className="py-5 px-4 text-right text-sm font-bold text-rose-600 dark:text-rose-400">{entry.payment > 0 ? entry.payment.toLocaleString('en-IN') : '-'}</td>
                      <td className={`py-5 px-4 text-right text-sm font-black bg-slate-50/30 dark:bg-slate-900/10 ${entry.running_balance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{entry.running_balance.toLocaleString('en-IN')}</td>
                      <td className="py-5 px-4 text-center no-print relative">
                        <button 
                          onClick={() => setActiveTxMenuId(activeTxMenuId === entry.id ? null : entry.id)}
                          className="p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
                        >
                          <MoreVertical className="w-4 h-4 text-slate-400" />
                        </button>

                        {activeTxMenuId === entry.id && (
                          <div className="absolute right-0 top-full mt-1 z-50 bg-white dark:bg-slate-800 shadow-2xl rounded-xl border border-slate-200 dark:border-slate-700 p-1 min-w-[120px] animate-in zoom-in-95 fade-in duration-200">
                            <button onClick={() => handleEditTx(entry)} className="w-full flex items-center gap-2 px-3 py-2 text-[10px] font-black uppercase tracking-widest text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg">
                              <Edit2 className="w-3 h-3" /> Edit
                            </button>
                            <button onClick={() => handleDeleteTx(entry.id)} className="w-full flex items-center gap-2 px-3 py-2 text-[10px] font-black uppercase tracking-widest text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-900/10 rounded-lg">
                              <Trash2 className="w-3 h-3" /> Delete
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr className="border-t-2 border-slate-900 dark:border-slate-100 bg-slate-50 dark:bg-slate-900 font-black">
                    <td colSpan={2} className="py-6 px-4 text-[10px] uppercase tracking-[0.3em] text-slate-500">Statement Totals:</td>
                    <td className="py-6 px-4 text-right text-base text-emerald-600">{tCredit.toLocaleString('en-IN')}</td>
                    <td className="py-6 px-4 text-right text-base text-rose-600">{tPayment.toLocaleString('en-IN')}</td>
                    <td className={`py-6 px-4 text-right text-xl ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>{finalBalance.toLocaleString('en-IN')}</td>
                    <td className="no-print"></td>
                  </tr>
                </tfoot>
              </table>
            </div>

            <div className="mt-24 grid grid-cols-2 gap-24">
