import React, { useState, useEffect, useCallback } from 'react';
import { Landmark, AlertTriangle } from 'lucide-react';
import { Party, Transaction, Product, Expense, Sale, User, TabType } from './types';
import { dbService } from './services/supabaseService';
// Import supabaseUrl directly to fix protected property access error
import { supabase, supabaseUrl } from './services/supabaseClient';
import Auth from './components/Auth';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import Ledger from './components/Ledger';
import Inventory from './components/Inventory';
import Settings from './components/Settings';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>('dashboard');
  const [parties, setParties] = useState<Party[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [sales, setSales] = useState<Sale[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [selectedParty, setSelectedParty] = useState<Party | null>(null);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [loading, setLoading] = useState(true);
  const [isMisconfigured, setIsMisconfigured] = useState(false);

  const [stats, setStats] = useState({
    totalCredit: 0,
    totalCollected: 0,
    totalOutstanding: 0,
    totalSales: 0,
    totalExpenses: 0,
    inventoryValue: 0
  });

  const refreshData = useCallback(async () => {
    if (!user) return;
    try {
      const db = await dbService.getInitialData();
      setParties(db.parties);
      setProducts(db.products);
      setSales(db.sales);
      setExpenses(db.expenses);
      setTransactions(db.transactions);

      const totalCredit = db.transactions.reduce((sum, item) => sum + (Number(item.credit) || 0), 0);
      const totalCollected = db.transactions.reduce((sum, item) => sum + (Number(item.payment) || 0), 0);
      const totalSales = db.sales.reduce((sum, item) => sum + (Number(item.total_amount) || 0), 0);
      const totalExpenses = db.expenses.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
      const inventoryValue = db.products.reduce((sum, item) => sum + ((Number(item.buying_price) || 0) * (Number(item.stock) || 0)), 0);

      setStats({
        totalCredit,
        totalCollected,
        totalOutstanding: totalCredit - totalCollected,
        totalSales,
        totalExpenses,
        inventoryValue
      });
    } catch (err) {
      console.error('Failed to fetch data:', err);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    // Check for misconfiguration on mount using exported supabaseUrl to avoid protected property access
    const isPlaceholder = supabaseUrl.includes('placeholder-project.supabase.co');
    if (isPlaceholder) {
      setIsMisconfigured(true);
      setLoading(false);
      return;
    }

    // 1. Initial Session Check
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          business_name: session.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
        });
      } else {
        setLoading(false);
      }
    });

    // 2. Auth Change Listener
    const { data: { subscription: authSub } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email!,
          business_name: session.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
        });
      } else {
        setUser(null);
        setParties([]);
        setTransactions([]);
        setProducts([]);
        setStats({
          totalCredit: 0,
          totalCollected: 0,
          totalOutstanding: 0,
          totalSales: 0,
          totalExpenses: 0,
          inventoryValue: 0
        });
      }
    });

    return () => authSub.unsubscribe();
  }, []);

  useEffect(() => {
    if (user && !isMisconfigured) {
      refreshData();

      // 3. Real-time Database Subscription
      const channel = supabase
        .channel('db_changes')
        .on('postgres_changes', { event: '*', schema: 'public' }, () => {
          refreshData();
        })
        .subscribe();

      return () => {
        supabase.removeChannel(channel);
      };
    }
  }, [user, refreshData, isMisconfigured]);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogin = async (e: string, p: string) => {
    const res = await dbService.login(e, p);
    return res;
  };

  const handleSignup = async (e: string, p: string, b: string) => {
    const res = await dbService.signup(e, p, b);
    return res;
  };

  const handleLogout = async () => {
    await dbService.logout();
    setUser(null);
  };

  const handleAddParty = async (name: string, phone: string) => {
    try {
      await dbService.addParty({ name, phone });
      await refreshData();
    } catch (err: any) {
      alert(`Error adding party: ${err.message || 'Unknown error'}`);
    }
  };

  const handleEditParty = async (id: string, updates: Partial<Party>) => {
    try {
      await dbService.updateParty(id, updates);
      await refreshData();
    } catch (err: any) {
      alert(`Error updating party: ${err.message || 'Unknown error'}`);
    }
  };

  const handleDeleteParty = async (id: string) => {
    if (!confirm('Are you sure you want to delete this party? All related transactions will be lost.')) return;
    try {
      await dbService.deleteParty(id);
      if (selectedParty?.id === id) setSelectedParty(null);
      await refreshData();
    } catch (err: any) {
      alert(`Error deleting party: ${err.message || 'Unknown error'}`);
    }
  };

  const handleAddTransaction = async (data: Omit<Transaction, 'id' | 'created_at'>) => {
    try {
      await dbService.addTransaction(data);
      await refreshData();
    } catch (err: any) {
      alert(`Error adding transaction: ${err.message || 'Unknown error'}`);
    }
  };

  const handleEditTransaction = async (id: string, updates: Partial<Transaction>) => {
    try {
      await dbService.updateTransaction(id, updates);
      await refreshData();
    } catch (err: any) {
      alert(`Error updating transaction: ${err.message || 'Unknown error'}`);
    }
  };

  const handleDeleteTransaction = async (id: string) => {
    if (!confirm('Delete this transaction record?')) return;
    try {
      await dbService.deleteTransaction(id);
      await refreshData();
    } catch (err: any) {
      alert(`Error deleting transaction: ${err.message || 'Unknown error'}`);
    }
  };

  const handleAddProduct = async (p: Omit<Product, 'id'>) => {
    try {
      await dbService.addProduct(p);
      await refreshData();
    } catch (err: any) {
      alert(`Error adding product: ${err.message || 'Unknown error'}`);
    }
  };

  const handleUpdateProfile = async (email: string, biz: string) => {
    try {
      const updatedUser = await dbService.updateProfile(email, biz);
      setUser(updatedUser);
    } catch (err: any) {
      throw err;
    }
  };

  if (loading && !user && !isMisconfigured) {
    return (
      <div className="h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-950">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  if (isMisconfigured) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-slate-50 dark:bg-slate-950">
        <div className="max-w-md w-full bg-white dark:bg-slate-900 p-10 rounded-[2.5rem] shadow-2xl border border-rose-100 dark:border-rose-900/30 text-center">
          <div className="inline-flex p-5 bg-rose-50 dark:bg-rose-900/20 rounded-full mb-6">
            <AlertTriangle className="w-10 h-10 text-rose-500" />
          </div>
          <h1 className="text-2xl font-black text-slate-900 dark:text-white uppercase tracking-tight mb-4">Configuration Required</h1>
          <p className="text-slate-500 dark:text-slate-400 text-sm leading-relaxed mb-8">
            The Supabase backend is not configured. Please set the following environment variables in your project settings:
            <div className="mt-4 space-y-2 text-left bg-slate-50 dark:bg-slate-800/50 p-4 rounded-xl font-mono text-xs">
              <div className="flex justify-between">
                <span className="text-slate-400">Variable</span>
                <span className="text-slate-400">Status</span>
              </div>
              <div className="flex justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                <span className="text-rose-500">SUPABASE_URL</span>
                <span className="text-rose-500 italic">Missing</span>
              </div>
              <div className="flex justify-between border-t border-slate-100 dark:border-slate-800 pt-2">
                <span className="text-rose-500">SUPABASE_ANON_KEY</span>
                <span className="text-rose-500 italic">Missing</span>
              </div>
            </div>
          </p>
          <div className="pt-6 border-t border-slate-100 dark:border-slate-800">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest leading-loose">
              Once configured, the app will enable cloud sync and authentication.
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (!user) {
    return <Auth onLogin={handleLogin} onSignup={handleSignup} />;
  }

  return (
    <div className="flex h-screen overflow-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        parties={parties}
        selectedParty={selectedParty}
        setSelectedParty={setSelectedParty}
        isDarkMode={isDarkMode}
        toggleDarkMode={() => setIsDarkMode(!isDarkMode)}
        onLogout={handleLogout}
        onEditParty={handleEditParty}
        onDeleteParty={handleDeleteParty}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-10 no-print">
        {activeTab === 'dashboard' && <Dashboard stats={stats} user={user} />}
        {activeTab === 'ledger' && (
          <Ledger 
            parties={parties} 
            selectedParty={selectedParty} 
            transactions={selectedParty ? transactions.filter(t => t.party_id === selectedParty.id) : []}
            user={user}
            onAddParty={handleAddParty}
            onAddTransaction={handleAddTransaction}
            onEditTransaction={handleEditTransaction}
            onDeleteTransaction={handleDeleteTransaction}
          />
        )}
        {activeTab === 'inventory' && (
          <Inventory 
            products={products}
            onAddProduct={handleAddProduct}
          />
        )}
        {activeTab === 'settings' && (
          <Settings 
            user={user}
            onUpdateProfile={handleUpdateProfile}
          />
        )}
        {['sales', 'expenses'].includes(activeTab) && (
          <div className="h-full flex flex-col items-center justify-center text-center py-20 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-200 dark:border-slate-800">
             <Landmark className="w-12 h-12 text-slate-300 mb-6" />
             <h2 className="text-xl font-black uppercase tracking-widest text-slate-400">Coming Soon</h2>
             <p className="text-xs text-slate-500 mt-2">Enhanced {activeTab} modules are under development.</p>
          </div>
        )}
      </main>

      {/* Print View Mirror */}
      <div className="hidden print:block fixed inset-0 bg-white z-[100] p-0 overflow-visible">
         {activeTab === 'ledger' && selectedParty && (
           <Ledger 
              parties={parties} 
              selectedParty={selectedParty} 
              transactions={transactions.filter(t => t.party_id === selectedParty.id)}
              user={user}
              onAddParty={handleAddParty}
              onAddTransaction={handleAddTransaction}
              onEditTransaction={handleEditTransaction}
              onDeleteTransaction={handleDeleteTransaction}
            />
         )}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { User, Plus, ReceiptText, UserPlus, Search, FileText, MoreVertical, Edit2, Trash2, Download } from 'lucide-react';
import { Party, Transaction, User as UserType } from '../types';

interface LedgerProps {
  parties: Party[];
  selectedParty: Party | null;
  transactions: Transaction[];
  user: UserType | null;
  onAddParty: (name: string, phone: string) => Promise<void>;
  onAddTransaction: (data: Omit<Transaction, 'id' | 'created_at'>) => Promise<void>;
  onEditTransaction: (id: string, updates: Partial<Transaction>) => Promise<void>;
  onDeleteTransaction: (id: string) => Promise<void>;
}

const Ledger: React.FC<LedgerProps> = ({ 
  parties, selectedParty, transactions, user, onAddParty, 
  onAddTransaction, onEditTransaction, onDeleteTransaction 
}) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [amount, setAmount] = useState('');
  const [type, setType] = useState<'credit' | 'payment'>('credit');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activeTxMenuId, setActiveTxMenuId] = useState<string | null>(null);
  const longPressTimer = useRef<number | null>(null);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddParty(partyName, partyPhone);
      setPartyName('');
      setPartyPhone('');
      setShowPartyForm(false);
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty || isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddTransaction({
        party_id: selectedParty.id,
        date,
        bill_no: billNo || 'N/A',
        credit: type === 'credit' ? Number(amount) : 0,
        payment: type === 'payment' ? Number(amount) : 0,
      });
      setAmount('');
      setBillNo('');
    } catch (err: any) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleEditTx = (tx: Transaction) => {
    const newDate = prompt('Enter new Date (YYYY-MM-DD):', tx.date);
    const newBill = prompt('Enter new Bill No:', tx.bill_no);
    if (newDate && newBill) {
      onEditTransaction(tx.id, { date: newDate, bill_no: newBill });
    }
    setActiveTxMenuId(null);
  };

  const handleDeleteTx = (id: string) => {
    onDeleteTransaction(id);
    setActiveTxMenuId(null);
  };

  const startLongPress = (id: string) => {
    longPressTimer.current = window.setTimeout(() => {
      setActiveTxMenuId(id);
    }, 600);
  };

  const cancelLongPress = () => {
    if (longPressTimer.current) {
      window.clearTimeout(longPressTimer.current);
      longPressTimer.current = null;
    }
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
      new Date(a.date).getTime() - new Date(b.date).getTime()
    );

    const entries = sortedTxs.map(t => {
      balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
      tCredit += (Number(t.credit) || 0);
      tPayment += (Number(t.payment) || 0);
      return { ...t, running_balance: balance };
    });

    return { entries, tCredit, tPayment, finalBalance: balance };
  };

  const { entries, tCredit, tPayment, finalBalance } = calculateLedger();

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 animate-in fade-in duration-500 relative">
      <div className="xl:col-span-1 space-y-8 no-print">
