              </div>

              <button type="submit" disabled={isSubmitting} className={`w-full font-black py-4 rounded-2xl transition-all flex items-center justify-center gap-3 shadow-lg shadow-black/10 active:scale-95 uppercase text-xs tracking-[0.2em] ${type === 'credit' ? 'bg-primary-600 hover:bg-primary-700' : 'bg-emerald-600 hover:bg-emerald-700'} text-white`}>
                <Plus className="w-5 h-5" />
                {isSubmitting ? 'Saving...' : `Save ${type} Entry`}
              </button>
            </form>
          )}
        </div>

        {/* New Party Section */}
        <div className="bg-white dark:bg-slate-900 p-8 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-3">
              <div className="p-3 bg-emerald-50 dark:bg-emerald-900/20 rounded-xl">
