                <input type="text" placeholder="Full Name" required value={partyName} onChange={e => setPartyName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 focus:ring-primary-500 outline-none" />
