          </div>
        ) : (
          <div className="bg-white dark:bg-slate-950 p-10 md:p-16 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-xl overflow-hidden ledger-container">
            <div className="flex flex-col md:flex-row justify-between items-start border-b-2 border-slate-900 dark:border-slate-100 pb-10 mb-10 gap-6">
              <div className="space-y-2">
                <h1 className="text-5xl font-black text-slate-900 dark:text-white uppercase tracking-tighter">
                  {user?.business_name || 'Business Ledger'}
                </h1>
                <p className="text-xs font-black text-slate-400 uppercase tracking-[0.3em]">Official Business Statement</p>
