                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Credit (+)</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white">Payment (-)</th>
                    <th className="py-5 px-4 text-right text-[10px] font-black uppercase tracking-wider text-slate-900 dark:text-white bg-slate-100 dark:bg-slate-900">Balance</th>
