                <button type="button" onClick={() => setEntryType('payment')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${entryType === 'payment' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-500'}`}>Payment</button>
              </div>

              <div className="grid grid-cols-2 gap-4">
