                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Details / Model Name</label>
                <input type="text" placeholder="e.g. Flower Design B+H" value={details} onChange={e => setDetails(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 ring-primary-500 outline-none" />
