                    <input type="number" placeholder="0.00" value={rate} onChange={e => setRate(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3.5 text-sm font-bold focus:ring-2 ring-primary-500 outline-none" />
