// Import supabaseUrl directly to fix protected property access error
import { supabase, supabaseUrl } from './supabaseClient';
import { Party, Transaction, Product, Expense, Sale } from '../types';

const isConfigured = () => {
  // Using exported supabaseUrl instead of the protected instance property
  return !supabaseUrl.includes('placeholder-project.supabase.co');
};

export const dbService = {
  login: async (email: string, pass: string) => {
    if (!isConfigured()) return { success: false, message: 'Supabase configuration is missing.' };

    const { data, error } = await supabase.auth.signInWithPassword({
      email,
      password: pass,
    });
    if (error) return { success: false, message: error.message };

    const user = {
      id: data.user.id,
      email: data.user.email!,
      business_name: data.user.user_metadata?.business_name || 'EMBRODERY STATEMENT'
    };
    return { success: true, user };
  },

  signup: async (email: string, pass: string, businessName: string) => {
    if (!isConfigured()) return { success: false, message: 'Supabase configuration is missing.' };

    const { data, error } = await supabase.auth.signUp({
      email,
      password: pass,
      options: {
        data: {
          business_name: businessName,
        }
      }
    });
    if (error) return { success: false, message: error.message };

    if (data.user && !data.session) {
      return { success: true, message: 'Signup successful! Please check your email for verification.' };
    }

    const user = {
      id: data.user!.id,
      email: data.user!.email!,
      business_name: businessName
    };
    return { success: true, user };
  },

  updateProfile: async (email: string, businessName: string) => {
    if (!isConfigured()) throw new Error('Supabase not configured');

    const { data, error } = await supabase.auth.updateUser({
      email: email,
      data: { business_name: businessName }
    });

    if (error) throw error;

    return {
      id: data.user.id,
      email: data.user.email!,
      business_name: data.user.user_metadata?.business_name || businessName
    };
  },

  logout: async () => {
    if (isConfigured()) {
      await supabase.auth.signOut();
    }
  },

  getInitialData: async () => {
    if (!isConfigured()) return { parties: [], transactions: [], products: [], expenses: [], sales: [] };

    const [parties, txs, products, expenses, sales] = await Promise.all([
      supabase.from('Parties').select('*'),
      supabase.from('Transactions').select('*').order('date', { ascending: true }),
      supabase.from('Products').select('*'),
      supabase.from('Expenses').select('*'),
      supabase.from('Sales').select('*'),
    ]);

    return {
      parties: parties.data || [],
      transactions: txs.data || [],
      products: products.data || [],
      expenses: expenses.data || [],
      sales: sales.data || []
