import React, { useState, useRef } from 'react';
import { User, Plus, ReceiptText, UserPlus, Search, FileText, MoreVertical, Trash2, Download, Eye, Loader2, CheckCircle2, Landmark, Phone } from 'lucide-react';
import { Party, Transaction, User as UserType } from '../types';
import * as htmlToImage from 'html-to-image';

interface LedgerProps {
  parties: Party[];
  selectedParty: Party | null;
  transactions: Transaction[];
  user: UserType | null;
  onAddParty: (name: string, phone: string) => Promise<void>;
  onAddTransaction: (data: Omit<Transaction, 'id' | 'created_at'>) => Promise<void>;
  onEditTransaction: (id: string, updates: Partial<Transaction>) => Promise<void>;
  onDeleteTransaction: (id: string) => Promise<void>;
}

const Ledger: React.FC<LedgerProps> = ({ 
  parties, selectedParty, transactions, user, onAddParty, 
  onAddTransaction, onEditTransaction, onDeleteTransaction 
}) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [details, setDetails] = useState('');
  const [pcs, setPcs] = useState<string>('');
  const [rate, setRate] = useState<string>('');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [entryType, setEntryType] = useState<'work' | 'payment'>('work');

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [showDownloadSuccess, setShowDownloadSuccess] = useState(false);

  const ledgerRef = useRef<HTMLDivElement>(null);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddParty(partyName, partyPhone);
      setPartyName('');
      setPartyPhone('');
      setShowPartyForm(false);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty || isSubmitting) return;
    setIsSubmitting(true);

    try {
      const numPcs = Number(pcs) || 0;
      const numRate = Number(rate) || 0;

      await onAddTransaction({
        party_id: selectedParty.id,
        date,
        bill_no: billNo || 'N/A',
        details: details || (entryType === 'payment' ? 'Cash Payment' : 'Embroidery Work'),
        pcs: entryType === 'work' ? numPcs : 0,
        rate: entryType === 'work' ? numRate : 0,
        credit: entryType === 'work' ? (numPcs * numRate) : 0,
        payment: entryType === 'payment' ? Number(paymentAmount) : 0,
      });

      setDetails('');
      setPcs('');
      setRate('');
      setPaymentAmount('');
      setBillNo('');
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDownloadHD = async () => {
    if (!ledgerRef.current || isDownloading) return;

    setIsDownloading(true);
    try {
      // Delay to ensure rendering is settled
      await new Promise(r => setTimeout(r, 500));

      const dataUrl = await htmlToImage.toPng(ledgerRef.current, {
        quality: 1,
        pixelRatio: 3, // High quality enough for zoom but manageable size
        backgroundColor: '#ffffff',
        style: {
          padding: '40px',
          borderRadius: '0',
          background: '#ffffff',
        }
      });

      const link = document.createElement('a');
      link.download = `${selectedParty?.name}_${new Date().toLocaleDateString()}.png`;
      link.href = dataUrl;
      link.click();

      setShowDownloadSuccess(true);
      setTimeout(() => setShowDownloadSuccess(false), 3000);
    } catch (err) {
      console.error('Download failed:', err);
      alert('Download failed. Try again.');
    } finally {
      setIsDownloading(false);
    }
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
      new Date(a.date).getTime() - new Date(b.date).getTime()
    );

    const entries = sortedTxs.map(t => {
      balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
      tCredit += (Number(t.credit) || 0);
      tPayment += (Number(t.payment) || 0);
      return { ...t, running_balance: balance };
    });

    return { entries, tCredit, tPayment, finalBalance: balance };
  };

  const { entries, tCredit, tPayment, finalBalance } = calculateLedger();

  return (
    <div className="flex flex-col lg:flex-row gap-8 pb-20 animate-in fade-in duration-500">

      {/* Forms Section */}
      <div className="w-full lg:w-1/3 space-y-8 no-print">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <ReceiptText className="w-5 h-5 text-primary-500" />
            <h3 className="font-black uppercase text-sm">Entry Hisab</h3>
          </div>

          {!selectedParty ? (
            <div className="py-10 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">Choose a party from sidebar first</p>
            </div>
          ) : (
            <form onSubmit={handleTxSubmit} className="space-y-4">
              <div className="flex gap-2 p-1 bg-slate-100 dark:bg-slate-800 rounded-xl">
                <button type="button" onClick={() => setEntryType('work')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${entryType === 'work' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600' : 'text-slate-500'}`}>Work</button>
                <button type="button" onClick={() => setEntryType('payment')} className={`flex-1 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${entryType === 'payment' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-500'}`}>Payment</button>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <input type="date" value={date} onChange={e => setDate(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full" />
                <input type="text" placeholder="Bill No" value={billNo} onChange={e => setBillNo(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full" />
              </div>

              <input type="text" placeholder="Model Name / Details" value={details} onChange={e => setDetails(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold" />

              {entryType === 'work' ? (
                <div className="grid grid-cols-2 gap-3">
                  <input type="number" placeholder="Pis (Qty)" value={pcs} onChange={e => setPcs(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full" />
                  <input type="number" placeholder="Rate" value={rate} onChange={e => setRate(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full" />
                </div>
              ) : (
                <input type="number" placeholder="Amount" value={paymentAmount} onChange={e => setPaymentAmount(e.target.value)} className="w-full bg-emerald-50 dark:bg-emerald-900/10 border-none rounded-xl p-3 text-lg font-black text-emerald-600" />
              )}

              <button type="submit" disabled={isSubmitting} className={`w-full font-black py-4 rounded-xl shadow-lg transition-all active:scale-95 uppercase text-[10px] tracking-widest ${entryType === 'work' ? 'bg-primary-600' : 'bg-emerald-600'} text-white`}>
                {isSubmitting ? 'Saving...' : `Save ${entryType}`}
              </button>
            </form>
          )}
        </div>

        {/* New Party Form */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
          <button onClick={() => setShowPartyForm(!showPartyForm)} className="flex items-center justify-between w-full">
            <div className="flex items-center gap-3">
              <UserPlus className="w-5 h-5 text-slate-400" />
              <h3 className="font-black uppercase text-sm">Add Party</h3>
            </div>
            <Plus className={`w-4 h-4 transition-transform ${showPartyForm ? 'rotate-45' : ''}`} />
          </button>
          {showPartyForm && (
            <form onSubmit={handlePartySubmit} className="mt-4 space-y-3 animate-in slide-in-from-top-2">
              <input placeholder="Name" required value={partyName} onChange={e => setPartyName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold" />
              <input placeholder="Phone" value={partyPhone} onChange={e => setPartyPhone(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold" />
              <button type="submit" className="w-full bg-slate-900 dark:bg-white dark:text-slate-900 text-white font-black py-3 rounded-xl text-[10px] uppercase">Create Party</button>
            </form>
          )}
        </div>
      </div>

      {/* Statement Preview Section */}
      <div className="w-full lg:w-2/3">
        {!selectedParty ? (
          <div className="h-full min-h-[400px] bg-white dark:bg-slate-900 rounded-[2.5rem] flex flex-col items-center justify-center p-12 text-center border-2 border-dashed border-slate-100 dark:border-slate-800">
            <Landmark className="w-12 h-12 text-slate-200 mb-4" />
            <h2 className="text-xl font-black uppercase text-slate-400">Select a party to view hisab</h2>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Header with Download Button */}
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 px-2 no-print">
              <div>
                <h2 className="text-xl font-black uppercase tracking-tighter">{selectedParty.name}</h2>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Digital Statement Preview</p>
              </div>
              <button 
                onClick={handleDownloadHD} 
                disabled={isDownloading}
                className="w-full sm:w-auto flex items-center justify-center gap-3 bg-slate-900 dark:bg-slate-800 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-black transition-all shadow-xl disabled:opacity-50"
              >
                {isDownloading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
                {isDownloading ? 'Processing...' : 'Download JPG'}
              </button>
            </div>

            {/* THE ACTUAL MEMO (CAPTURED AREA) */}
            <div className="overflow-hidden rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-2xl">
              <div 
                ref={ledgerRef}
                className="bg-white text-slate-900 p-8 md:p-12 min-h-[800px] relative"
                style={{ width: '100%', maxWidth: '800px', margin: '0 auto' }}
              >
                {/* Official Header */}
                <div className="flex flex-col md:flex-row justify-between items-start border-b-4 border-slate-900 pb-8 mb-8 gap-4">
                  <div>
                    <h1 className="text-3xl md:text-5xl font-black uppercase tracking-tighter leading-none">{user?.business_name || 'Business'}</h1>
                    <p className="text-xs font-black text-slate-500 uppercase tracking-widest mt-2">Embroidery Hisab & Bill Statement</p>
                  </div>
                  <div className="text-right flex flex-col items-end">
                    <span className="text-sm font-black uppercase">Date: {new Date().toLocaleDateString('en-GB')}</span>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Ref: {Math.random().toString(36).substr(2, 6).toUpperCase()}</span>
                  </div>
                </div>

                {/* Customer Details & Net Balance */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-10">
                  <div className="bg-slate-50 p-6 border-l-4 border-slate-900">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Customer Details</p>
                    <h3 className="text-2xl font-black uppercase">{selectedParty.name}</h3>
                    <div className="flex items-center gap-2 text-slate-600 mt-2 font-mono text-xs">
                      <Phone className="w-3 h-3" /> {selectedParty.phone || 'N/A'}
                    </div>
                  </div>
                  <div className="flex flex-col justify-center items-center md:items-end">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Outstanding</p>
                    <div className={`text-5xl font-black tracking-tighter ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                      ৳ {finalBalance.toLocaleString('en-IN')}
                    </div>
                  </div>
                </div>

                {/* Main Table */}
                <div className="overflow-x-auto">
                  <table className="w-full border-collapse">
                    <thead>
                      <tr className="border-y-2 border-slate-900 bg-slate-50">
                        <th className="py-4 px-3 text-left text-[10px] font-black uppercase">Date</th>
                        <th className="py-4 px-3 text-left text-[10px] font-black uppercase">Bill</th>
                        <th className="py-4 px-3 text-left text-[10px] font-black uppercase">Details</th>
                        <th className="py-4 px-3 text-right text-[10px] font-black uppercase">Qty</th>
                        <th className="py-4 px-3 text-right text-[10px] font-black uppercase">Rate</th>
                        <th className="py-4 px-3 text-right text-[10px] font-black uppercase">Amount</th>
                        <th className="py-4 px-3 text-right text-[10px] font-black uppercase">Paid</th>
                        <th className="py-4 px-3 text-right text-[10px] font-black uppercase bg-slate-100">Balance</th>
                        <th className="no-print py-4 px-3 text-center text-[10px] font-black uppercase">Action</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {entries.length === 0 ? (
                        <tr><td colSpan={9} className="py-20 text-center text-slate-300 font-black uppercase text-[10px]">No entries found</td></tr>
                      ) : entries.map(entry => (
                        <tr key={entry.id} className="text-[11px] hover:bg-slate-50/50">
                          <td className="py-4 px-3 font-mono whitespace-nowrap">{new Date(entry.date).toLocaleDateString('en-GB')}</td>
