                          <td className="py-4 px-3 font-medium uppercase truncate max-w-[150px]">{entry.details}</td>
                          <td className="py-4 px-3 text-right font-mono">{entry.pcs || '-'}</td>
                          <td className="py-4 px-3 text-right font-mono">{entry.rate || '-'}</td>
                          <td className="py-4 px-3 text-right font-bold">{entry.credit > 0 ? entry.credit.toLocaleString() : '-'}</td>
                          <td className="py-4 px-3 text-right font-bold text-emerald-600">{entry.payment > 0 ? entry.payment.toLocaleString() : '-'}</td>
                          <td className={`py-4 px-3 text-right font-black bg-slate-50/50 ${entry.running_balance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                            {entry.running_balance.toLocaleString()}
                          </td>
                          <td className="no-print py-4 px-3 text-center">
                            <button onClick={() => onDeleteTransaction(entry.id)} className="p-1.5 text-rose-300 hover:text-rose-600 transition-colors">
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="border-t-4 border-slate-900 bg-slate-50 font-black text-xs">
                        <td colSpan={5} className="py-6 px-3 uppercase text-[10px] text-slate-400">Total Statement Calculations:</td>
                        <td className="py-6 px-3 text-right">{tCredit.toLocaleString()}</td>
                        <td className="py-6 px-3 text-right text-emerald-600">{tPayment.toLocaleString()}</td>
                        <td className={`py-6 px-3 text-right text-lg ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                          {finalBalance.toLocaleString()}
                        </td>
                        <td className="no-print"></td>
                      </tr>
                    </tfoot>
                  </table>
                </div>

                {/* Footer Signatures */}
                <div className="mt-24 flex justify-between gap-12">
                  <div className="flex-1 border-t-2 border-slate-900 pt-3 text-center">
                    <p className="text-[9px] font-black uppercase tracking-widest">Party Signature</p>
                  </div>
                  <div className="flex-1 border-t-2 border-slate-900 pt-3 text-center">
                    <p className="text-[9px] font-black uppercase tracking-widest">Authorized Signature</p>
                  </div>
                </div>

                <div className="mt-12 pt-6 border-t border-slate-100 text-center">
                   <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.4em]">Digital Statement - Powered by Embrodery Statement App</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {showDownloadSuccess && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-8 py-4 rounded-full shadow-2xl flex items-center gap-3 animate-in slide-in-from-bottom-4">
          <CheckCircle2 className="w-5 h-5" />
          <span className="text-[10px] font-black uppercase tracking-widest">Hisab Saved Successfully!</span>
        </div>
      )}
    </div>
  );
};

export default Ledger;

import React, { useState, useRef } from 'react';
import { User, Plus, ReceiptText, UserPlus, Search, FileText, MoreVertical, Trash2, Download, Eye, Loader2, CheckCircle2, Landmark, Phone, X } from 'lucide-react';
import { Party, Transaction, User as UserType } from '../types';
import * as htmlToImage from 'html-to-image';

interface LedgerProps {
  parties: Party[];
  selectedParty: Party | null;
  transactions: Transaction[];
  user: UserType | null;
  onAddParty: (name: string, phone: string) => Promise<void>;
  onAddTransaction: (data: Omit<Transaction, 'id' | 'created_at'>) => Promise<void>;
  onEditTransaction: (id: string, updates: Partial<Transaction>) => Promise<void>;
  onDeleteTransaction: (id: string) => Promise<void>;
}

const Ledger: React.FC<LedgerProps> = ({ 
  parties, selectedParty, transactions, user, onAddParty, 
  onAddTransaction, onEditTransaction, onDeleteTransaction 
}) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [details, setDetails] = useState('');
  const [pcs, setPcs] = useState<string>('');
  const [rate, setRate] = useState<string>('');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [entryType, setEntryType] = useState<'work' | 'payment'>('work');

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [showDownloadSuccess, setShowDownloadSuccess] = useState(false);

  const ledgerRef = useRef<HTMLDivElement>(null);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddParty(partyName, partyPhone);
      setPartyName('');
      setPartyPhone('');
      setShowPartyForm(false);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty || isSubmitting) return;
    setIsSubmitting(true);

    try {
      const numPcs = Number(pcs) || 0;
      const numRate = Number(rate) || 0;

      await onAddTransaction({
        party_id: selectedParty.id,
        date,
        bill_no: billNo || 'N/A',
        details: details || (entryType === 'payment' ? 'Cash Payment' : 'Embroidery Work'),
        pcs: entryType === 'work' ? numPcs : 0,
        rate: entryType === 'work' ? numRate : 0,
        credit: entryType === 'work' ? (numPcs * numRate) : 0,
        payment: entryType === 'payment' ? Number(paymentAmount) : 0,
      });

      setDetails('');
      setPcs('');
      setRate('');
      setPaymentAmount('');
      setBillNo('');
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDownloadHD = async () => {
    if (!ledgerRef.current || isDownloading) return;

    setIsDownloading(true);
    try {
      // Small delay to ensure everything is rendered
      await new Promise(r => setTimeout(r, 800));

      const dataUrl = await htmlToImage.toPng(ledgerRef.current, {
        quality: 1,
        pixelRatio: 4, // Higher pixel ratio for ultra-clear text
        backgroundColor: '#ffffff',
        style: {
          padding: '40px',
          borderRadius: '0',
          background: '#ffffff',
        }
      });

      const link = document.createElement('a');
      link.download = `${selectedParty?.name}_${date}.png`;
      link.href = dataUrl;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setShowDownloadSuccess(true);
      setTimeout(() => setShowDownloadSuccess(false), 3000);
    } catch (err) {
      console.error('Download failed:', err);
      alert('Download failed! Please try again using Chrome or Safari.');
    } finally {
      setIsDownloading(false);
    }
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
      new Date(a.date).getTime() - new Date(b.date).getTime()
    );

    const entries = sortedTxs.map(t => {
      balance = balance + (Number(t.credit) || 0) - (Number(t.payment) || 0);
      tCredit += (Number(t.credit) || 0);
      tPayment += (Number(t.payment) || 0);
      return { ...t, running_balance: balance };
    });

    return { entries, tCredit, tPayment, finalBalance: balance };
  };

  const { entries, tCredit, tPayment, finalBalance } = calculateLedger();

  return (
    <div className="flex flex-col xl:flex-row gap-8 pb-24">

      {/* Forms Section */}
      <div className="w-full xl:w-[350px] space-y-6 no-print order-2 xl:order-1">
        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <ReceiptText className="w-5 h-5 text-primary-500" />
            <h3 className="font-black uppercase text-xs tracking-widest">Entry Hisab</h3>
          </div>

          {!selectedParty ? (
            <div className="py-10 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-2xl">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">Choose a party first</p>
            </div>
          ) : (
            <form onSubmit={handleTxSubmit} className="space-y-4">
              <div className="flex gap-2 p-1 bg-slate-100 dark:bg-slate-800 rounded-xl">
                <button type="button" onClick={() => setEntryType('work')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${entryType === 'work' ? 'bg-white dark:bg-slate-700 shadow-sm text-primary-600' : 'text-slate-500'}`}>Work</button>
                <button type="button" onClick={() => setEntryType('payment')} className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${entryType === 'payment' ? 'bg-white dark:bg-slate-700 shadow-sm text-emerald-600' : 'text-slate-500'}`}>Payment</button>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <input type="date" value={date} onChange={e => setDate(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full outline-none focus:ring-2 ring-primary-500" />
                <input type="text" placeholder="Bill No" value={billNo} onChange={e => setBillNo(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full outline-none focus:ring-2 ring-primary-500" />
              </div>

              <input type="text" placeholder="Model Name / Details" value={details} onChange={e => setDetails(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold outline-none focus:ring-2 ring-primary-500" />

              {entryType === 'work' ? (
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase px-1">Pcs</label>
                    <input type="number" placeholder="0" value={pcs} onChange={e => setPcs(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full outline-none focus:ring-2 ring-primary-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase px-1">Rate</label>
                    <input type="number" placeholder="0.00" value={rate} onChange={e => setRate(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full outline-none focus:ring-2 ring-primary-500" />
                  </div>
                </div>
              ) : (
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase px-1">Cash Amount</label>
                  <input type="number" placeholder="0.00" value={paymentAmount} onChange={e => setPaymentAmount(e.target.value)} className="w-full bg-emerald-50 dark:bg-emerald-900/10 border-none rounded-xl p-4 text-xl font-black text-emerald-600 outline-none focus:ring-2 ring-emerald-500" />
                </div>
              )}

              <button type="submit" disabled={isSubmitting} className={`w-full font-black py-4 rounded-xl shadow-lg transition-all active:scale-95 uppercase text-[10px] tracking-widest ${entryType === 'work' ? 'bg-primary-600' : 'bg-emerald-600'} text-white`}>
                {isSubmitting ? 'Saving...' : `Save ${entryType}`}
              </button>
            </form>
          )}
        </div>

        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
          <button onClick={() => setShowPartyForm(!showPartyForm)} className="flex items-center justify-between w-full">
            <div className="flex items-center gap-3">
              <UserPlus className="w-5 h-5 text-slate-400" />
              <h3 className="font-black uppercase text-xs tracking-widest">Add Party</h3>
            </div>
            <Plus className={`w-4 h-4 transition-transform ${showPartyForm ? 'rotate-45' : ''}`} />
          </button>
          {showPartyForm && (
            <form onSubmit={handlePartySubmit} className="mt-4 space-y-3 animate-in slide-in-from-top-2">
              <input placeholder="Party Name" required value={partyName} onChange={e => setPartyName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold outline-none focus:ring-2 ring-primary-500" />
              <input placeholder="Phone" value={partyPhone} onChange={e => setPartyPhone(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold outline-none focus:ring-2 ring-primary-500" />
              <button type="submit" className="w-full bg-slate-900 dark:bg-white dark:text-slate-900 text-white font-black py-3 rounded-xl text-[10px] uppercase">Create Party</button>
            </form>
          )}
        </div>
      </div>

      {/* Statement Preview Section */}
      <div className="flex-1 order-1 xl:order-2">
        {!selectedParty ? (
          <div className="h-full min-h-[400px] bg-white dark:bg-slate-900 rounded-[3rem] flex flex-col items-center justify-center p-12 text-center border-2 border-dashed border-slate-100 dark:border-slate-800">
            <div className="p-6 bg-slate-50 dark:bg-slate-800 rounded-full mb-6">
              <Landmark className="w-10 h-10 text-slate-300" />
            </div>
            <h2 className="text-lg font-black uppercase text-slate-400 tracking-widest">Select a party to view hisab</h2>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Header Controls */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm no-print">
              <div>
                <h2 className="text-2xl font-black uppercase tracking-tighter text-slate-900 dark:text-white">{selectedParty.name}</h2>
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
                  <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                  Statement Preview
                </div>
              </div>
              <button 
                onClick={handleDownloadHD} 
                disabled={isDownloading}
                className="w-full md:w-auto flex items-center justify-center gap-3 bg-slate-900 dark:bg-primary-600 text-white px-10 py-5 rounded-[1.5rem] font-black text-xs uppercase tracking-[0.2em] hover:scale-[1.02] active:scale-95 transition-all shadow-2xl disabled:opacity-50"
              >
                {isDownloading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Download className="w-5 h-5" />}
                {isDownloading ? 'Generating Image...' : 'Download Statement (JPG)'}
              </button>
            </div>

            {/* PREVIEW CONTAINER - Clear and Readable */}
            <div className="relative">
              {/* This scroll container is for viewing on mobile */}
              <div className="overflow-x-auto pb-4 scrollbar-thin">
                <div 
                  ref={ledgerRef}
                  className="bg-white text-slate-900 p-8 md:p-16 min-h-[900px] shadow-2xl mx-auto"
                  style={{ width: '100%', minWidth: '750px', maxWidth: '850px' }}
                >
                  {/* Business Branding */}
                  <div className="flex flex-col md:flex-row justify-between items-start border-b-4 border-slate-950 pb-8 mb-10 gap-6">
                    <div>
                      <h1 className="text-4xl md:text-6xl font-black uppercase tracking-tighter leading-none">{user?.business_name || 'Business'}</h1>
                      <p className="text-sm font-black text-slate-500 uppercase tracking-[0.4em] mt-3">Embroidery Hisab & Bill Memo</p>
                    </div>
                    <div className="text-right flex flex-col items-end">
                      <div className="bg-slate-900 text-white px-4 py-2 rounded-lg text-sm font-black mb-2">
                        DATE: {new Date().toLocaleDateString('en-GB')}
                      </div>
                      <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Statement ID: {selectedParty.id.slice(0,8).toUpperCase()}</span>
                    </div>
                  </div>

                  {/* Info Header */}
                  <div className="grid grid-cols-2 gap-10 mb-12">
                    <div className="bg-slate-50 p-6 rounded-2xl border-l-8 border-slate-900">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Customer Details</p>
                      <h3 className="text-3xl font-black uppercase leading-tight">{selectedParty.name}</h3>
                      <div className="flex items-center gap-2 text-slate-600 mt-3 font-mono text-sm font-bold">
                        <Phone className="w-4 h-4" /> {selectedParty.phone || 'N/A'}
                      </div>
                    </div>
                    <div className="flex flex-col justify-center items-end">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Net Outstanding Balance</p>
                      <div className={`text-6xl font-black tracking-tighter leading-none ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                        ৳{finalBalance.toLocaleString('en-IN')}
                      </div>
                    </div>
                  </div>

                  {/* Data Table - FIXED: No blue blocks, high contrast */}
                  <div className="w-full">
                    <table className="w-full border-collapse">
                      <thead>
                        <tr className="border-y-4 border-slate-950 bg-slate-50 text-slate-900">
                          <th className="py-5 px-4 text-left text-[11px] font-black uppercase tracking-wider">Date</th>
                          <th className="py-5 px-4 text-left text-[11px] font-black uppercase tracking-wider">LOT No</th>
                          <th className="py-5 px-4 text-left text-[11px] font-black uppercase tracking-wider">Details</th>
                          <th className="py-5 px-4 text-right text-[11px] font-black uppercase tracking-wider">Qty</th>
                          <th className="py-5 px-4 text-right text-[11px] font-black uppercase tracking-wider">Rate</th>
                          <th className="py-5 px-4 text-right text-[11px] font-black uppercase tracking-wider">Bill (+)</th>
                          <th className="py-5 px-4 text-right text-[11px] font-black uppercase tracking-wider">Cash (-)</th>
                          <th className="py-5 px-4 text-right text-[11px] font-black uppercase tracking-wider bg-slate-100">Balance</th>
                          <th className="no-print py-5 px-4 text-center text-[10px] font-black uppercase tracking-widest text-slate-400">Del</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y-2 divide-slate-100">
                        {entries.length === 0 ? (
                          <tr><td colSpan={9} className="py-32 text-center text-slate-300 font-black uppercase text-sm tracking-widest">No entries found</td></tr>
                        ) : entries.map(entry => (
                          <tr key={entry.id} className="text-slate-800">
                            <td className="py-5 px-4 text-xs font-bold whitespace-nowrap">{new Date(entry.date).toLocaleDateString('en-GB')}</td>
                            <td className="py-5 px-4 text-xs font-black">{entry.bill_no}</td>
                            <td className="py-5 px-4 text-xs font-bold uppercase tracking-tight">{entry.details}</td>
                            <td className="py-5 px-4 text-right text-xs font-bold">{entry.pcs || '-'}</td>
                            <td className="py-5 px-4 text-right text-xs font-bold">{entry.rate || '-'}</td>
                            <td className="py-5 px-4 text-right text-sm font-black">{entry.credit > 0 ? entry.credit.toLocaleString() : '-'}</td>
                            <td className="py-5 px-4 text-right text-sm font-black text-emerald-600">{entry.payment > 0 ? entry.payment.toLocaleString() : '-'}</td>
                            <td className={`py-5 px-4 text-right text-sm font-black bg-slate-50 ${entry.running_balance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                              {entry.running_balance.toLocaleString()}
                            </td>
                            <td className="no-print py-5 px-4 text-center">
                              <button onClick={() => onDeleteTransaction(entry.id)} className="p-2 text-rose-300 hover:text-rose-600 transition-colors">
                                <Trash2 className="w-4 h-4" />
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                      <tfoot>
                        <tr className="border-t-4 border-slate-950 bg-slate-50 font-black text-slate-950">
                          <td colSpan={5} className="py-8 px-4 uppercase text-[10px] text-slate-500 tracking-widest">Calculated Summary:</td>
                          <td className="py-8 px-4 text-right text-lg">{tCredit.toLocaleString()}</td>
                          <td className="py-8 px-4 text-right text-lg text-emerald-600">{tPayment.toLocaleString()}</td>
                          <td className={`py-8 px-4 text-right text-3xl ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                            ৳{finalBalance.toLocaleString()}
                          </td>
                          <td className="no-print"></td>
                        </tr>
                      </tfoot>
                    </table>
                  </div>

                  {/* Signatures */}
                  <div className="mt-32 flex justify-between gap-16 px-4">
                    <div className="flex-1 border-t-4 border-slate-950 pt-4 text-center">
                      <p className="text-[11px] font-black uppercase tracking-[0.2em]">Party Signature</p>
                    </div>
                    <div className="flex-1 border-t-4 border-slate-950 pt-4 text-center">
                      <p className="text-[11px] font-black uppercase tracking-[0.2em]">Authorized Signature</p>
                    </div>
                  </div>

                  {/* Note */}
                  <div className="mt-16 pt-8 border-t border-slate-100 text-center">
                     <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.5em]">Computer Generated Statement • Verified Data</p>
                  </div>
                </div>
              </div>

              {/* Mobile Swipe Tip */}
              <div className="md:hidden text-center mt-2 no-print">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest animate-pulse">← Swipe left/right to see full memo →</p>
              </div>
            </div>
          </div>
        )}
      </div>

      {showDownloadSuccess && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-slate-900 text-white px-10 py-5 rounded-full shadow-2xl flex items-center gap-4 animate-in slide-in-from-bottom-6 duration-500">
          <div className="bg-emerald-500 p-1 rounded-full"><CheckCircle2 className="w-4 h-4" /></div>
          <span className="text-xs font-black uppercase tracking-[0.2em]">Statement Image Downloaded</span>
        </div>
      )}
    </div>
  );
};

export default Ledger;

import React, { useState, useRef } from 'react';
import { User, Plus, ReceiptText, UserPlus, Search, FileText, MoreVertical, Trash2, Download, Eye, Loader2, CheckCircle2, Landmark, Phone, X } from 'lucide-react';
import { Party, Transaction, User as UserType } from '../types';
import * as htmlToImage from 'html-to-image';

interface LedgerProps {
  parties: Party[];
  selectedParty: Party | null;
  transactions: Transaction[];
  user: UserType | null;
  onAddParty: (name: string, phone: string) => Promise<void>;
  onAddTransaction: (data: Omit<Transaction, 'id' | 'created_at'>) => Promise<void>;
  onEditTransaction: (id: string, updates: Partial<Transaction>) => Promise<void>;
  onDeleteTransaction: (id: string) => Promise<void>;
}

const Ledger: React.FC<LedgerProps> = ({ 
  parties, selectedParty, transactions, user, onAddParty, 
  onAddTransaction, onEditTransaction, onDeleteTransaction 
}) => {
  const [showPartyForm, setShowPartyForm] = useState(false);
  const [partyName, setPartyName] = useState('');
  const [partyPhone, setPartyPhone] = useState('');

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [billNo, setBillNo] = useState('');
  const [details, setDetails] = useState('');
  const [pcs, setPcs] = useState<string>('');
  const [rate, setRate] = useState<string>('');
  const [paymentAmount, setPaymentAmount] = useState<string>('');
  const [entryType, setEntryType] = useState<'work' | 'payment'>('work');

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [showDownloadSuccess, setShowDownloadSuccess] = useState(false);

  const ledgerRef = useRef<HTMLDivElement>(null);

  const handlePartySubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;
    setIsSubmitting(true);
    try {
      await onAddParty(partyName, partyPhone);
      setPartyName('');
      setPartyPhone('');
      setShowPartyForm(false);
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTxSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedParty || isSubmitting) return;
    setIsSubmitting(true);

    try {
      const numPcs = Number(pcs) || 0;
      const numRate = Number(rate) || 0;

      await onAddTransaction({
        party_id: selectedParty.id,
        date,
        bill_no: billNo || 'N/A',
        details: details || (entryType === 'payment' ? 'Cash Payment' : 'Embroidery Work'),
        pcs: entryType === 'work' ? numPcs : 0,
        rate: entryType === 'work' ? numRate : 0,
        credit: entryType === 'work' ? (numPcs * numRate) : 0,
        payment: entryType === 'payment' ? Number(paymentAmount) : 0,
      });

      setDetails('');
      setPcs('');
      setRate('');
      setPaymentAmount('');
      setBillNo('');
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDownloadHD = async () => {
    if (!ledgerRef.current || isDownloading) return;

    setIsDownloading(true);
    try {
      // Clear selection and menus
      window.getSelection()?.removeAllRanges();

      // Wait for font rendering
      await new Promise(r => setTimeout(r, 1000));

      const dataUrl = await htmlToImage.toJpeg(ledgerRef.current, {
        quality: 1,
        pixelRatio: 4, 
        backgroundColor: '#ffffff',
        // Filter out elements that shouldn't be in the image
        filter: (node) => {
          if (node instanceof HTMLElement && node.classList.contains('no-print')) return false;
          return true;
        },
        style: {
          padding: '40px',
          background: '#ffffff',
          borderRadius: '0',
          margin: '0',
        }
      });

      const link = document.createElement('a');
      link.download = `${selectedParty?.name}_Hisab_${date}.jpg`;
      link.href = dataUrl;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      setShowDownloadSuccess(true);
      setTimeout(() => setShowDownloadSuccess(false), 3000);
    } catch (err) {
      console.error('Download error:', err);
      alert('Mobile download error. Try using a browser like Chrome or Safari, or take a screenshot.');
    } finally {
      setIsDownloading(false);
    }
  };

  const calculateLedger = () => {
    let balance = 0;
    let tCredit = 0;
    let tPayment = 0;

    const sortedTxs = [...transactions].sort((a, b) => 
