              <ReceiptText className="w-5 h-5 text-primary-600" />
            </div>
            <h3 className="font-black uppercase text-xs tracking-widest text-slate-900 dark:text-white">Quick Entry</h3>
          </div>

          {!selectedParty ? (
            <div className="py-12 text-center border-2 border-dashed border-slate-100 dark:border-slate-800 rounded-3xl">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] px-4">Select a party first</p>
            </div>
          ) : (
            <form onSubmit={handleTxSubmit} className="space-y-4">
