                  <input type="text" placeholder="No" value={billNo} onChange={e => setBillNo(e.target.value)} className="bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold w-full outline-none focus:ring-2 ring-primary-500" />
                </div>
              </div>

              <div className="space-y-1">
