              <button type="submit" disabled={isSubmitting} className={`w-full font-black py-4 rounded-2xl shadow-xl transition-all active:scale-95 uppercase text-[10px] tracking-widest ${entryType === 'work' ? 'bg-primary-600' : 'bg-emerald-600'} text-white mt-2`}>
                {isSubmitting ? 'Saving...' : `Confirm ${entryType}`}
              </button>
            </form>
          )}
        </div>

        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2rem] border border-slate-200 dark:border-slate-800 shadow-sm">
          <button onClick={() => setShowPartyForm(!showPartyForm)} className="flex items-center justify-between w-full">
            <div className="flex items-center gap-3">
              <UserPlus className="w-5 h-5 text-slate-400" />
              <h3 className="font-black uppercase text-xs tracking-widest text-slate-900 dark:text-white">Create Party</h3>
            </div>
            <Plus className={`w-4 h-4 transition-transform ${showPartyForm ? 'rotate-45' : ''}`} />
          </button>
          {showPartyForm && (
            <form onSubmit={handlePartySubmit} className="mt-4 space-y-3 animate-in slide-in-from-top-2">
              <input placeholder="Party Name" required value={partyName} onChange={e => setPartyName(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold outline-none focus:ring-2 ring-primary-500" />
              <input placeholder="Phone" value={partyPhone} onChange={e => setPartyPhone(e.target.value)} className="w-full bg-slate-50 dark:bg-slate-800 border-none rounded-xl p-3 text-xs font-bold outline-none focus:ring-2 ring-primary-500" />
              <button type="submit" className="w-full bg-slate-900 dark:bg-white dark:text-slate-900 text-white font-black py-3 rounded-xl text-[10px] uppercase">Add Party</button>
            </form>
          )}
        </div>
      </div>

      {/* Simplified Memo Display Area */}
      <div className="flex-1 order-1 xl:order-2">
        {!selectedParty ? (
          <div className="h-full min-h-[400px] bg-white dark:bg-slate-900 rounded-[3rem] flex flex-col items-center justify-center p-12 text-center border border-slate-200 dark:border-slate-800 shadow-sm">
            <div className="p-8 bg-slate-50 dark:bg-slate-800 rounded-full mb-6">
              <Landmark className="w-12 h-12 text-slate-200" />
            </div>
            <h2 className="text-xl font-black uppercase text-slate-400 tracking-widest">Select a party</h2>
          </div>
        ) : (
          <div className="space-y-6">
            {/* Action Bar */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-4 bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-lg no-print">
              <div>
                <h2 className="text-2xl font-black uppercase tracking-tighter text-slate-900 dark:text-white">{selectedParty.name}</h2>
                <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-1">
                  <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
                  Simplified Ledger View
                </div>
              </div>
              <button 
                onClick={handleDownloadHD} 
                disabled={isDownloading}
                className="w-full md:w-auto flex items-center justify-center gap-3 bg-slate-900 dark:bg-primary-600 text-white px-12 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] hover:scale-[1.02] active:scale-95 transition-all shadow-2xl disabled:opacity-50"
              >
                {isDownloading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Download className="w-5 h-5" />}
                {isDownloading ? 'Processing...' : 'Download Statement'}
              </button>
            </div>

            {/* CLEAN MEMO PREVIEW */}
            <div className="overflow-x-auto pb-6 ledger-preview-wrapper no-print">
              <div 
                ref={ledgerRef}
                className="bg-white text-slate-950 p-10 md:p-16 min-h-[1000px] shadow-2xl mx-auto"
                style={{ width: '100%', minWidth: '850px', maxWidth: '850px' }}
              >
                {/* Logo & Header */}
                <div className="flex flex-col md:flex-row justify-between items-start border-b-[6px] border-slate-950 pb-10 mb-12 gap-6">
                  <div>
                    <h1 className="text-5xl md:text-7xl font-black uppercase tracking-tighter leading-none">{user?.business_name || 'Business'}</h1>
                    <p className="text-base font-black text-slate-500 uppercase tracking-[0.5em] mt-4">Embroidery Statement Memo</p>
                  </div>
                  <div className="text-right flex flex-col items-end">
                    <div className="bg-slate-950 text-white px-6 py-3 rounded-lg text-lg font-black mb-3">
                      DATE: {new Date().toLocaleDateString('en-GB')}
                    </div>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest text-right">ACCOUNT ID: {selectedParty.id.slice(0,10).toUpperCase()}</span>
                  </div>
                </div>

                {/* Party & Balance Block */}
                <div className="grid grid-cols-2 gap-12 mb-16">
                  <div className="bg-slate-50 p-8 rounded-3xl border-l-[12px] border-slate-950">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Customer Info</p>
                    <h3 className="text-4xl font-black uppercase leading-tight mb-4">{selectedParty.name}</h3>
                    <div className="flex items-center gap-3 text-slate-700 font-mono text-base font-black">
                      <Phone className="w-5 h-5 text-slate-400" /> {selectedParty.phone || 'N/A'}
                    </div>
                  </div>
                  <div className="flex flex-col justify-center items-end text-right">
                    <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest mb-3">Final Outstanding Balance</p>
                    <div className={`text-7xl font-black tracking-tighter leading-none ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                      ৳{finalBalance.toLocaleString('en-IN')}
                    </div>
                  </div>
                </div>

                {/* Simplified Table */}
                <div className="w-full">
                  <table className="w-full border-collapse">
                    <thead>
                      <tr className="border-y-4 border-slate-950 text-slate-950 text-[13px]">
                        <th className="py-6 px-4 text-left font-black uppercase tracking-wider w-32">Date</th>
                        <th className="py-6 px-4 text-left font-black uppercase tracking-wider">Bill No</th>
                        <th className="py-6 px-4 text-right font-black uppercase tracking-wider">Bill Amount (+)</th>
                        <th className="py-6 px-4 text-right font-black uppercase tracking-wider">Cash Paid (-)</th>
                        <th className="py-6 px-4 text-right font-black uppercase tracking-wider border-l-2 border-slate-200">Net Balance</th>
                        <th className="no-print py-6 px-4 text-center text-[10px] font-black uppercase text-slate-300">Action</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y-[1px] divide-slate-200">
                      {entries.length === 0 ? (
                        <tr><td colSpan={6} className="py-40 text-center text-slate-300 font-black uppercase text-base tracking-widest">No entries found</td></tr>
                      ) : entries.map(entry => (
                        <tr key={entry.id} className="text-slate-900 text-sm">
                          <td className="py-6 px-4 font-bold whitespace-nowrap">{new Date(entry.date).toLocaleDateString('en-GB')}</td>
                          <td className="py-6 px-4 font-black">{entry.bill_no}</td>
                          <td className="py-6 px-4 text-right font-black">{entry.credit > 0 ? entry.credit.toLocaleString() : '-'}</td>
                          <td className="py-6 px-4 text-right font-black text-emerald-600">{entry.payment > 0 ? entry.payment.toLocaleString() : '-'}</td>
                          <td className={`py-6 px-4 text-right font-black border-l-2 border-slate-100 ${entry.running_balance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                            {entry.running_balance.toLocaleString()}
                          </td>
                          <td className="no-print py-6 px-4 text-center">
                            <button onClick={() => onDeleteTransaction(entry.id)} className="p-2 text-rose-200 hover:text-rose-500 transition-colors">
                              <Trash2 className="w-5 h-5" />
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="border-t-[6px] border-slate-950 font-black text-slate-950">
                        <td colSpan={2} className="py-10 px-4 uppercase text-[10px] text-slate-400 tracking-[0.3em]">Total Calculations:</td>
                        <td className="py-10 px-4 text-right text-2xl">{tCredit.toLocaleString()}</td>
                        <td className="py-10 px-4 text-right text-2xl text-emerald-600">{tPayment.toLocaleString()}</td>
                        <td className={`py-10 px-4 text-right text-5xl border-l-4 border-slate-950 ${finalBalance > 0 ? 'text-rose-600' : 'text-emerald-600'}`}>
                          ৳{finalBalance.toLocaleString()}
                        </td>
                        <td className="no-print"></td>
                      </tr>
                    </tfoot>
                  </table>
                </div>

                {/* Signatures */}
                <div className="mt-40 flex justify-between gap-24 px-8">
                  <div className="flex-1 border-t-4 border-slate-950 pt-5 text-center">
                    <p className="text-sm font-black uppercase tracking-[0.3em]">Customer Signature</p>
                  </div>
                  <div className="flex-1 border-t-4 border-slate-950 pt-5 text-center">
                    <p className="text-sm font-black uppercase tracking-[0.3em]">Authorized Signatory</p>
                  </div>
                </div>

                <div className="mt-20 pt-10 border-t border-slate-100 text-center">
                   <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.6em]">OFFICIAL DIGITAL STATEMENT • GENERATED SECURELY</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {showDownloadSuccess && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-slate-900 text-white px-10 py-5 rounded-full shadow-2xl flex items-center gap-4 animate-in slide-in-from-bottom-6">
          <CheckCircle2 className="w-5 h-5 text-emerald-500" />
          <span className="text-xs font-black uppercase tracking-[0.2em]">Statement Downloaded</span>
        </div>
      )}
    </div>
  );
};

export default Ledger;
